// Builders
// ---------------------------------------------------------------------------

/// Build the `$bitwise_to_i32` function.
///
/// Remaining raw escape hatches: none.
pub fn build_bitwise_to_i32() -> WasmFunction {
    WasmFunction::new("$bitwise_to_i32")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // tag
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::TAG_MASK),
            WasmInstr::I32And,
            WasmInstr::LocalSet(1),
            WasmInstr::Block("$after_numeric".to_owned()),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::NUMBER),
            WasmInstr::I32Eq,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::OBJECT),
            WasmInstr::I32Eq,
            WasmInstr::I32Or,
            WasmInstr::I32Eqz,
            WasmInstr::BrIfDepth(0),
            WasmInstr::LocalGet(0),
            WasmInstr::Call("$number_to_i32".to_owned()),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::Block("$after_true".to_owned()),
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::TRUE),
            WasmInstr::I32Eq,
            WasmInstr::I32Eqz,
            WasmInstr::BrIfDepth(0),
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::Block("$after_falsey".to_owned()),
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::FALSE),
            WasmInstr::I32Eq,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::NULL),
            WasmInstr::I32Eq,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::UNDEFINED),
            WasmInstr::I32Eq,
            WasmInstr::I32Or,
            WasmInstr::I32Or,
            WasmInstr::I32Eqz,
            WasmInstr::BrIfDepth(0),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::Unreachable,
        ])
}

/// Build the `$bitwise_and` function.
///
/// Generated WAT (flat instruction format):
/// ```wat
/// (func $bitwise_and (param i32) (param i32) (result i32)
///   (local.get 0)
///   (call $bitwise_to_i32)
///   (local.get 1)
///   (call $bitwise_to_i32)
///   (i32.and)
///   (call $number_from_i32))
/// ```
///
/// Remaining raw escape hatches: none.
pub fn build_bitwise_and() -> WasmFunction {
    WasmFunction::new("$bitwise_and")
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::Call("$bitwise_to_i32".to_owned()),
            WasmInstr::LocalGet(1),
            WasmInstr::Call("$bitwise_to_i32".to_owned()),
            WasmInstr::I32And,
            WasmInstr::Call("$number_from_i32".to_owned()),
        ])
}

