fn build_number_fast_delegate(symbol: &str, target: &str) -> WasmFunction {
    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .body(vec![
            WasmInstr::Block("$slow".to_owned()),
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::TAG_MASK),
            WasmInstr::I32And,
            WasmInstr::I32Const(ValueTag::NUMBER),
            WasmInstr::I32Eq,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::TAG_MASK),
            WasmInstr::I32And,
            WasmInstr::I32Const(ValueTag::NUMBER),
            WasmInstr::I32Eq,
            WasmInstr::I32And,
            WasmInstr::I32Eqz,
            WasmInstr::BrIfDepth(0),
            WasmInstr::LocalGet(0),
            WasmInstr::LocalGet(1),
            WasmInstr::Call(target.to_owned()),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::LocalGet(1),
            WasmInstr::Call(target.to_owned()),
        ])
}

