/// Build the `$string_char_code_at` function.
///
/// Returns a tagged numeric code point for known UTF-8 string receivers and a
/// tagged NaN sentinel for non-string, non-number index, or out-of-range cases.
/// Remaining raw escape hatches: none.
pub fn build_string_char_code_at() -> WasmFunction {
    let string_header = Layout::STRING_HEADER_SIZE as i32;
    let nan = tagged_number_sentinel(ValueTag::NAN_PAYLOAD);

    WasmFunction::new("$string_char_code_at")
        .param(WasmValType::I32) // local 0: tagged string
        .param(WasmValType::I32) // local 1: tagged index
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 2: heap string pointer
        .local(WasmValType::I32) // local 3: code point length
        .local(WasmValType::I32) // local 4: raw index
        .local(WasmValType::I32) // local 5: byte position
        .local(WasmValType::I32) // local 6: current byte address
        .local(WasmValType::I32) // local 7: byte 1
        .local(WasmValType::I32) // local 8: byte 2
        .local(WasmValType::I32) // local 9: byte 3
        .local(WasmValType::I32) // local 10: byte 4
        .local(WasmValType::I32) // local 11: decoded code point
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::Call("$is_string".to_owned()),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(nan),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::TAG_MASK),
            WasmInstr::I32And,
            WasmInstr::I32Const(ValueTag::NUMBER),
            WasmInstr::I32Ne,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(nan),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(nan),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(nan),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::HEAP_MASK),
            WasmInstr::I32And,
            WasmInstr::LocalSet(2),
            WasmInstr::LocalGet(2),
            WasmInstr::Call("$utf8_cp_count".to_owned()),
            WasmInstr::LocalSet(3),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
            WasmInstr::I32ShrS,
            WasmInstr::LocalSet(4),
            WasmInstr::LocalGet(4),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32LtS,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(nan),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(4),
            WasmInstr::LocalGet(3),
            WasmInstr::I32GeU,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(nan),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(2),
            WasmInstr::LocalGet(4),
            WasmInstr::Call("$utf8_cp_to_byte_index".to_owned()),
            WasmInstr::LocalSet(5),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(string_header),
            WasmInstr::I32Add,
            WasmInstr::LocalGet(5),
            WasmInstr::I32Add,
            WasmInstr::LocalSet(6),
            WasmInstr::LocalGet(6),
            WasmInstr::I32Load8U {
                align: 0,
                offset: 0,
            },
            WasmInstr::LocalSet(7),
            WasmInstr::Block("$decoded".to_owned()),
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(0x80),
            WasmInstr::I32LtU,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(7),
            WasmInstr::LocalSet(11),
            WasmInstr::Br("$decoded".to_owned()),
            WasmInstr::End,
            WasmInstr::LocalGet(6),
            WasmInstr::I32Const(1),
            WasmInstr::I32Add,
            WasmInstr::I32Load8U {
                align: 0,
                offset: 0,
            },
            WasmInstr::LocalSet(8),
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(0xE0),
            WasmInstr::I32LtU,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(0x1F),
            WasmInstr::I32And,
            WasmInstr::I32Const(6),
            WasmInstr::I32Shl,
            WasmInstr::LocalGet(8),
            WasmInstr::I32Const(0x3F),
            WasmInstr::I32And,
            WasmInstr::I32Or,
            WasmInstr::LocalSet(11),
            WasmInstr::Br("$decoded".to_owned()),
            WasmInstr::End,
            WasmInstr::LocalGet(6),
            WasmInstr::I32Const(2),
            WasmInstr::I32Add,
            WasmInstr::I32Load8U {
                align: 0,
                offset: 0,
            },
            WasmInstr::LocalSet(9),
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(0xF0),
            WasmInstr::I32LtU,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(0x0F),
            WasmInstr::I32And,
            WasmInstr::I32Const(12),
            WasmInstr::I32Shl,
            WasmInstr::LocalGet(8),
            WasmInstr::I32Const(0x3F),
            WasmInstr::I32And,
            WasmInstr::I32Const(6),
            WasmInstr::I32Shl,
            WasmInstr::I32Or,
            WasmInstr::LocalGet(9),
            WasmInstr::I32Const(0x3F),
            WasmInstr::I32And,
            WasmInstr::I32Or,
            WasmInstr::LocalSet(11),
            WasmInstr::Br("$decoded".to_owned()),
            WasmInstr::End,
            WasmInstr::LocalGet(6),
            WasmInstr::I32Const(3),
            WasmInstr::I32Add,
            WasmInstr::I32Load8U {
                align: 0,
                offset: 0,
            },
            WasmInstr::LocalSet(10),
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(0x07),
            WasmInstr::I32And,
            WasmInstr::I32Const(18),
            WasmInstr::I32Shl,
            WasmInstr::LocalGet(8),
            WasmInstr::I32Const(0x3F),
            WasmInstr::I32And,
            WasmInstr::I32Const(12),
            WasmInstr::I32Shl,
            WasmInstr::I32Or,
            WasmInstr::LocalGet(9),
            WasmInstr::I32Const(0x3F),
            WasmInstr::I32And,
            WasmInstr::I32Const(6),
            WasmInstr::I32Shl,
            WasmInstr::I32Or,
            WasmInstr::LocalGet(10),
            WasmInstr::I32Const(0x3F),
            WasmInstr::I32And,
            WasmInstr::I32Or,
            WasmInstr::LocalSet(11),
            WasmInstr::End,
            WasmInstr::LocalGet(11),
            WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
            WasmInstr::I32Shl,
            WasmInstr::I32Const(ValueTag::NUMBER),
            WasmInstr::I32Or,
        ])
}

fn append_string_single_code_point_copy(
    body: &mut Vec<WasmInstr>,
    tagged_string_local: usize,
    heap_obj_local: usize,
    byte_pos_local: usize,
    byte_len_local: usize,
    result_ptr_local: usize,
) {
    let string_header = Layout::STRING_HEADER_SIZE as i32;

    body.extend([
        WasmInstr::LocalGet(heap_obj_local),
        WasmInstr::LocalGet(byte_pos_local),
        WasmInstr::Call("$utf8_cp_byte_length".to_owned()),
        WasmInstr::LocalSet(byte_len_local),
        WasmInstr::I32Const(string_header),
        WasmInstr::LocalGet(byte_len_local),
        WasmInstr::I32Add,
        WasmInstr::Call("$alloc_heap".to_owned()),
        WasmInstr::LocalSet(result_ptr_local),
        WasmInstr::LocalGet(result_ptr_local),
        WasmInstr::LocalGet(byte_len_local),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(tagged_string_local),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Const(string_header),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(byte_pos_local),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(result_ptr_local),
        WasmInstr::I32Const(string_header),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(byte_len_local),
        WasmInstr::Call("$copy".to_owned()),
        WasmInstr::LocalGet(result_ptr_local),
        WasmInstr::I32Const(ValueTag::STRING_TAG as i32),
        WasmInstr::I32Or,
    ]);
}

/// Build the `$string_char_at` function.
///
/// Remaining raw escape hatches: none.
pub fn build_string_char_at() -> WasmFunction {
    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::Call("$is_string".to_owned()),
        WasmInstr::I32Eqz,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(2),
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32ShrS,
        WasmInstr::LocalSet(3),
        WasmInstr::LocalGet(3),
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::I32LtS,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(2),
        WasmInstr::LocalGet(3),
        WasmInstr::Call("$utf8_cp_to_byte_index".to_owned()),
        WasmInstr::LocalSet(4),
        WasmInstr::LocalGet(4),
        WasmInstr::LocalGet(2),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::I32GeU,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::Return,
        WasmInstr::End,
    ];

    append_string_single_code_point_copy(&mut body, 0, 2, 4, 5, 6);

    WasmFunction::new("$string_char_at")
        .param(WasmValType::I32) // local 0: tagged string
        .param(WasmValType::I32) // local 1: tagged index
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 2: heap string pointer
        .local(WasmValType::I32) // local 3: raw code point index
        .local(WasmValType::I32) // local 4: byte position
        .local(WasmValType::I32) // local 5: byte length
        .local(WasmValType::I32) // local 6: result pointer
        .body(body)
}

