#[derive(Clone, Copy)]
enum RegexpLiteralResult {
    Test,
    Match,
    Search,
}

fn push_tagged_number_from_local(body: &mut Vec<WasmInstr>, local: usize) {
    body.extend([
        WasmInstr::LocalGet(local),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32Shl,
        WasmInstr::I32Const(ValueTag::NUMBER),
        WasmInstr::I32Or,
    ]);
}

fn push_regexp_literal_failure(body: &mut Vec<WasmInstr>, result: RegexpLiteralResult) {
    match result {
        RegexpLiteralResult::Test => {
            body.push(WasmInstr::I32Const(ValueTag::FALSE));
        }
        RegexpLiteralResult::Match => {
            body.push(WasmInstr::I32Const(ValueTag::NULL));
        }
        RegexpLiteralResult::Search => {
            body.extend([
                WasmInstr::I32Const(-1),
                WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
                WasmInstr::I32Shl,
                WasmInstr::I32Const(ValueTag::NUMBER),
                WasmInstr::I32Or,
            ]);
        }
    }
    body.push(WasmInstr::Return);
}

fn push_regexp_literal_success(body: &mut Vec<WasmInstr>, result: RegexpLiteralResult) {
    match result {
        RegexpLiteralResult::Test => {
            body.push(WasmInstr::I32Const(ValueTag::TRUE));
        }
        RegexpLiteralResult::Search => {
            push_tagged_number_from_local(body, 7);
        }
        RegexpLiteralResult::Match => {
            body.push(WasmInstr::LocalGet(1));
            push_tagged_number_from_local(body, 7);
            body.extend([
                WasmInstr::LocalGet(7),
                WasmInstr::LocalGet(10),
                WasmInstr::I32Add,
                WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
                WasmInstr::I32Shl,
                WasmInstr::I32Const(ValueTag::NUMBER),
                WasmInstr::I32Or,
                WasmInstr::Call("$string_substring".to_owned()),
            ]);
        }
    }
    body.push(WasmInstr::Return);
}

fn build_regexp_literal_search(symbol: &str, result: RegexpLiteralResult) -> WasmFunction {
    let string_header = Layout::STRING_HEADER_SIZE as i32;

    let mut body = Vec::new();

    for local in [0, 1] {
        body.extend([
            WasmInstr::LocalGet(local),
            WasmInstr::Call("$is_string".to_owned()),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
        ]);
        push_regexp_literal_failure(&mut body, result);
        body.push(WasmInstr::End);
    }

    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(2),
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(3),
        WasmInstr::LocalGet(2),
        WasmInstr::I32Const(string_header),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(8),
        WasmInstr::LocalGet(3),
        WasmInstr::I32Const(string_header),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(9),
        WasmInstr::LocalGet(2),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(4),
        WasmInstr::LocalGet(3),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(5),
        WasmInstr::LocalGet(4),
        WasmInstr::I32Const(2),
        WasmInstr::I32LtU,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_regexp_literal_failure(&mut body, result);
    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(8),
        WasmInstr::I32Load8U {
            align: 0,
            offset: 0,
        },
        WasmInstr::I32Const(b'/' as i32),
        WasmInstr::I32Ne,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_regexp_literal_failure(&mut body, result);
    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(4),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Sub,
        WasmInstr::LocalSet(6),
        WasmInstr::Block("$regexp_delimiter_found".to_owned()),
        WasmInstr::Loop("$regexp_find_delimiter".to_owned()),
        WasmInstr::LocalGet(8),
        WasmInstr::LocalGet(6),
        WasmInstr::I32Add,
        WasmInstr::I32Load8U {
            align: 0,
            offset: 0,
        },
        WasmInstr::I32Const(b'/' as i32),
        WasmInstr::I32Eq,
        WasmInstr::BrIf("$regexp_delimiter_found".to_owned()),
        WasmInstr::LocalGet(6),
        WasmInstr::I32Eqz,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_regexp_literal_failure(&mut body, result);
    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(6),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Sub,
        WasmInstr::LocalSet(6),
        WasmInstr::Br("$regexp_find_delimiter".to_owned()),
        WasmInstr::End,
        WasmInstr::End,
        WasmInstr::LocalGet(6),
        WasmInstr::I32Eqz,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_regexp_literal_failure(&mut body, result);
    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(6),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_regexp_literal_success(&mut body, result);
    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(6),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Sub,
        WasmInstr::LocalSet(10),
        WasmInstr::LocalGet(10),
        WasmInstr::LocalGet(5),
        WasmInstr::I32GtU,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_regexp_literal_failure(&mut body, result);
    body.extend([
        WasmInstr::End,
        WasmInstr::Block("$regexp_not_found".to_owned()),
        WasmInstr::Loop("$regexp_search_loop".to_owned()),
        WasmInstr::LocalGet(7),
        WasmInstr::LocalGet(5),
        WasmInstr::LocalGet(10),
        WasmInstr::I32Sub,
        WasmInstr::I32GtU,
        WasmInstr::BrIf("$regexp_not_found".to_owned()),
        WasmInstr::LocalGet(8),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(9),
        WasmInstr::LocalGet(7),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(10),
        WasmInstr::Call("$mem_equal".to_owned()),
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_regexp_literal_success(&mut body, result);
    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(7),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(7),
        WasmInstr::Br("$regexp_search_loop".to_owned()),
        WasmInstr::End,
        WasmInstr::End,
    ]);
    push_regexp_literal_failure(&mut body, result);

    WasmFunction::new(symbol)
        .param(WasmValType::I32) // local 0: pattern string, including /.../ flags
        .param(WasmValType::I32) // local 1: input string
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 2: pattern heap pointer
        .local(WasmValType::I32) // local 3: input heap pointer
        .local(WasmValType::I32) // local 4: pattern byte length
        .local(WasmValType::I32) // local 5: input byte length
        .local(WasmValType::I32) // local 6: closing slash delimiter index
        .local(WasmValType::I32) // local 7: input search position
        .local(WasmValType::I32) // local 8: pattern bytes pointer
        .local(WasmValType::I32) // local 9: input bytes pointer
        .local(WasmValType::I32) // local 10: literal byte length
        .body(body)
}

pub fn build_regexp_test() -> WasmFunction {
    build_regexp_literal_search("$regexp_test", RegexpLiteralResult::Test)
}

pub fn build_regexp_match() -> WasmFunction {
    build_regexp_literal_search("$regexp_match", RegexpLiteralResult::Match)
}

pub fn build_regexp_search() -> WasmFunction {
    build_regexp_literal_search("$regexp_search", RegexpLiteralResult::Search)
}

