fn build_string_ascii_case(symbol: &str, first: i32, last: i32, delta: i32) -> WasmFunction {
    let string_header = Layout::STRING_HEADER_SIZE as i32;

    WasmFunction::new(symbol)
        .param(WasmValType::I32) // local 0: tagged string
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 1: string heap pointer
        .local(WasmValType::I32) // local 2: byte length
        .local(WasmValType::I32) // local 3: byte index
        .local(WasmValType::I32) // local 4: current byte
        .local(WasmValType::I32) // local 5: result heap pointer
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::Call("$is_string".to_owned()),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::UNDEFINED),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::HEAP_MASK),
            WasmInstr::I32And,
            WasmInstr::LocalSet(1),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Load {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalSet(2),
            WasmInstr::I32Const(string_header),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Add,
            WasmInstr::Call("$alloc_heap".to_owned()),
            WasmInstr::LocalSet(5),
            WasmInstr::LocalGet(5),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::Block("$case_done".to_owned()),
            WasmInstr::Loop("$case_loop".to_owned()),
            WasmInstr::LocalGet(3),
            WasmInstr::LocalGet(2),
            WasmInstr::I32GeU,
            WasmInstr::BrIf("$case_done".to_owned()),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(string_header),
            WasmInstr::I32Add,
            WasmInstr::LocalGet(3),
            WasmInstr::I32Add,
            WasmInstr::I32Load8U {
                align: 0,
                offset: 0,
            },
            WasmInstr::LocalSet(4),
            WasmInstr::LocalGet(4),
            WasmInstr::I32Const(first),
            WasmInstr::I32GeU,
            WasmInstr::LocalGet(4),
            WasmInstr::I32Const(last),
            WasmInstr::I32LeU,
            WasmInstr::I32And,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(4),
            WasmInstr::I32Const(delta),
            WasmInstr::I32Add,
            WasmInstr::LocalSet(4),
            WasmInstr::End,
            WasmInstr::LocalGet(5),
            WasmInstr::I32Const(string_header),
            WasmInstr::I32Add,
            WasmInstr::LocalGet(3),
            WasmInstr::I32Add,
            WasmInstr::LocalGet(4),
            WasmInstr::I32Store8 {
                align: 0,
                offset: 0,
            },
            WasmInstr::LocalGet(3),
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::I32Add,
            WasmInstr::LocalSet(3),
            WasmInstr::Br("$case_loop".to_owned()),
            WasmInstr::End,
            WasmInstr::End,
            WasmInstr::LocalGet(5),
            WasmInstr::I32Const(ValueTag::STRING_TAG as i32),
            WasmInstr::I32Or,
        ])
}

