/// Build the `$string_code_point_at` function.
///
/// The native runtime stores strings as UTF-8 and indexes by decoded code
/// points. Reuse `$string_char_code_at` for the decode path and map its
/// out-of-range/non-string tagged NaN sentinel to JavaScript `undefined`.
/// Remaining raw escape hatches: none.
pub fn build_string_code_point_at() -> WasmFunction {
    let nan = tagged_number_sentinel(ValueTag::NAN_PAYLOAD);

    WasmFunction::new("$string_code_point_at")
        .param(WasmValType::I32) // local 0: tagged string
        .param(WasmValType::I32) // local 1: tagged index
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 2: tagged decoded value
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::LocalGet(1),
            WasmInstr::Call("$string_char_code_at".to_owned()),
            WasmInstr::LocalSet(2),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(nan),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::UNDEFINED),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(2),
        ])
}

