fn build_runtime_catchable_error(
    symbol: &str,
    params: usize,
    data: RuntimeCatchableErrorData,
) -> WasmFunction {
    let object_size = (Layout::OBJECT_HEADER_SIZE + Layout::OBJECT_ENTRY_SIZE) as i32;
    let object_flags_offset = Layout::OBJECT_FLAGS_OFFSET as i32;
    let object_prototype_offset = Layout::OBJECT_PROTOTYPE_OFFSET as i32;
    let object_entries_offset = Layout::OBJECT_ENTRIES_OFFSET as i32;
    let object_entry_value_offset =
        (Layout::OBJECT_ENTRIES_OFFSET + Layout::OBJECT_VALUE_OFFSET) as i32;
    let error_obj = params;

    let mut function = WasmFunction::new(symbol);
    for _ in 0..params {
        function = function.param(WasmValType::I32);
    }

    function
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .body(vec![
            WasmInstr::GlobalGet("$exception_handler_depth".to_owned()),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(data.diagnostic.ptr),
            WasmInstr::I32Const(data.diagnostic.len),
            WasmInstr::Call("$write".to_owned()),
            WasmInstr::Unreachable,
            WasmInstr::End,
            WasmInstr::I32Const(object_size),
            WasmInstr::Call("$alloc_heap".to_owned()),
            WasmInstr::LocalSet(error_obj),
            WasmInstr::LocalGet(error_obj),
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(error_obj),
            WasmInstr::I32Const(object_flags_offset),
            WasmInstr::I32Add,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(error_obj),
            WasmInstr::I32Const(object_prototype_offset),
            WasmInstr::I32Add,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(error_obj),
            WasmInstr::I32Const(object_entries_offset),
            WasmInstr::I32Add,
            WasmInstr::I32Const(data.message_key),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(error_obj),
            WasmInstr::I32Const(object_entry_value_offset),
            WasmInstr::I32Add,
            WasmInstr::I32Const(data.message_value),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(error_obj),
            WasmInstr::I32Const(ValueTag::OBJECT),
            WasmInstr::I32Or,
            WasmInstr::GlobalSet("$exception_pending".to_owned()),
            WasmInstr::I32Const(ValueTag::UNDEFINED),
        ])
}

/// Build the `$bigint_division_by_zero_range_error` function.
