/// Build the `$bigint_from_value` function.
///
/// Remaining raw escape hatches: none.
pub fn build_bigint_from_value() -> WasmFunction {
    let tag_mask = ValueTag::TAG_MASK;
    let number_tag = ValueTag::NUMBER;
    let number_shift = ValueTag::NUMBER_SHIFT;

    WasmFunction::new("$bigint_from_value")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::Call("$is_bigint".to_owned()),
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(0),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::Call("$is_string".to_owned()),
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(0),
            WasmInstr::Call("$bigint_from_string".to_owned()),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(tag_mask),
            WasmInstr::I32And,
            WasmInstr::I32Const(number_tag),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(number_shift),
            WasmInstr::I32ShrS,
            WasmInstr::I64ExtendI32S,
            WasmInstr::Call("$bigint_from_signed_i64".to_owned()),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::TRUE),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I64Const(1),
            WasmInstr::Call("$bigint_from_signed_i64".to_owned()),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::FALSE),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I64Const(0),
            WasmInstr::Call("$bigint_from_signed_i64".to_owned()),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::Unreachable,
        ])
}

/// Build the `$bigint_copy_with_sign` helper.
///
/// Copies an existing BigInt decimal payload with a replacement sign. Negative
/// copies are materialized through scratch memory so the leading minus byte can
/// be prepended without mutating the source object.
