fn build_collection_new_with_proto(symbol: &str, proto_global: &str) -> WasmFunction {
    let collection_size = (Layout::OBJECT_HEADER_SIZE + (32 * Layout::OBJECT_ENTRY_SIZE)) as i32;
    let obj_header = Layout::OBJECT_HEADER_SIZE as i32;
    let obj_flags = Layout::OBJECT_FLAGS_OFFSET as i32;
    let obj_proto = Layout::OBJECT_PROTOTYPE_OFFSET as i32;
    let heap_mask = ValueTag::HEAP_MASK;

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // base
        .body(vec![
            WasmInstr::GlobalGet(proto_global.to_owned()),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(obj_header),
            WasmInstr::Call("$alloc_heap".to_owned()),
            WasmInstr::GlobalSet(proto_global.to_owned()),
            WasmInstr::GlobalGet(proto_global.to_owned()),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::GlobalGet(proto_global.to_owned()),
            WasmInstr::I32Const(obj_flags),
            WasmInstr::I32Add,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::GlobalGet(proto_global.to_owned()),
            WasmInstr::I32Const(obj_proto),
            WasmInstr::I32Add,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::End,
            WasmInstr::I32Const(collection_size),
            WasmInstr::Call("$alloc_heap".to_owned()),
            WasmInstr::LocalSet(1),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(obj_flags),
            WasmInstr::I32Add,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(obj_proto),
            WasmInstr::I32Add,
            WasmInstr::GlobalGet(proto_global.to_owned()),
            WasmInstr::I32Const(heap_mask),
            WasmInstr::I32And,
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::OBJECT),
            WasmInstr::I32Or,
        ])
}

