fn collection_entry_addr(base: usize, index: usize) -> Vec<WasmInstr> {
    vec![
        WasmInstr::LocalGet(base),
        WasmInstr::I32Const(Layout::OBJECT_HEADER_SIZE as i32),
        WasmInstr::LocalGet(index),
        WasmInstr::I32Const(Layout::OBJECT_ENTRY_SHIFT as i32),
        WasmInstr::I32Shl,
        WasmInstr::I32Add,
        WasmInstr::I32Add,
    ]
}

fn build_collection_lookup(
    symbol: &str,
    cmp_symbol: &str,
    found_value: Vec<WasmInstr>,
) -> WasmFunction {
    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(2),
        WasmInstr::LocalGet(2),
        WasmInstr::I32Const(ValueTag::OBJECT),
        WasmInstr::I32Ne,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(if symbol.ends_with("_get") {
            ValueTag::UNDEFINED
        } else {
            ValueTag::FALSE
        }),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(3),
        WasmInstr::LocalGet(3),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(4),
        WasmInstr::LocalGet(4),
        WasmInstr::LocalSet(5),
        WasmInstr::Block("$not_found".to_owned()),
        WasmInstr::Loop("$scan".to_owned()),
        WasmInstr::LocalGet(5),
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::I32Eq,
        WasmInstr::BrIf("$not_found".to_owned()),
        WasmInstr::LocalGet(5),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Sub,
        WasmInstr::LocalSet(5),
    ];
    body.extend(collection_entry_addr(3, 5));
    body.extend([
        WasmInstr::LocalSet(6),
        WasmInstr::LocalGet(6),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(1),
        WasmInstr::Call(cmp_symbol.to_owned()),
        WasmInstr::I32Const(ValueTag::TRUE),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    body.extend(found_value);
    body.extend([
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::Br("$scan".to_owned()),
        WasmInstr::End,
        WasmInstr::End,
        WasmInstr::I32Const(if symbol.ends_with("_get") {
            ValueTag::UNDEFINED
        } else {
            ValueTag::FALSE
        }),
    ]);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // tag
        .local(WasmValType::I32) // base
        .local(WasmValType::I32) // count
        .local(WasmValType::I32) // i
        .local(WasmValType::I32) // entry_base
        .body(body)
}

fn build_collection_set_like(
    symbol: &str,
    cmp_symbol: &str,
    value_param: u32,
    stored_value: Vec<WasmInstr>,
) -> WasmFunction {
    let params = if value_param == 2 { 3 } else { 2 };
    let tag = params;
    let base = params + 1;
    let count = params + 2;
    let i = params + 3;
    let entry_base = params + 4;
    let mut f = WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32);
    if params == 3 {
        f = f.param(WasmValType::I32);
    }

    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(tag),
        WasmInstr::LocalGet(tag),
        WasmInstr::I32Const(ValueTag::OBJECT),
        WasmInstr::I32Ne,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(base),
        WasmInstr::LocalGet(base),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(count),
        WasmInstr::LocalGet(count),
        WasmInstr::LocalSet(i),
        WasmInstr::Block("$append".to_owned()),
        WasmInstr::Loop("$scan".to_owned()),
        WasmInstr::LocalGet(i),
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::I32Eq,
        WasmInstr::BrIf("$append".to_owned()),
        WasmInstr::LocalGet(i),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Sub,
        WasmInstr::LocalSet(i),
    ];
    body.extend(collection_entry_addr(base, i));
    body.extend([
        WasmInstr::LocalSet(entry_base),
        WasmInstr::LocalGet(entry_base),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(1),
        WasmInstr::Call(cmp_symbol.to_owned()),
        WasmInstr::I32Const(ValueTag::TRUE),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    if value_param == 2 {
        body.extend([
            WasmInstr::LocalGet(entry_base),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Store {
                align: 2,
                offset: Layout::OBJECT_VALUE_OFFSET as u32,
            },
        ]);
    }
    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::Br("$scan".to_owned()),
        WasmInstr::End,
        WasmInstr::End,
    ]);
    body.extend(collection_entry_addr(base, count));
    body.extend([
        WasmInstr::LocalSet(entry_base),
        WasmInstr::LocalGet(entry_base),
        WasmInstr::LocalGet(1),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(entry_base),
    ]);
    body.extend(stored_value);
    body.extend([
        WasmInstr::I32Store {
            align: 2,
            offset: Layout::OBJECT_VALUE_OFFSET as u32,
        },
        WasmInstr::LocalGet(base),
        WasmInstr::LocalGet(count),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Add,
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(0),
    ]);

    f.local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

