fn build_set_algebra(symbol: &str) -> WasmFunction {
    let base = 2;
    let len = 3;
    let i = 4;
    let entry_base = 5;
    let value = 6;
    let result = 7;
    let tag = 8;
    let mut body = vec![];
    if symbol == "$set_intersection" {
        body.extend([
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::TAG_MASK),
            WasmInstr::I32And,
            WasmInstr::LocalSet(tag),
            WasmInstr::LocalGet(tag),
            WasmInstr::I32Const(ValueTag::OBJECT),
            WasmInstr::I32Ne,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::UNDEFINED),
            WasmInstr::Call("$set_new".to_owned()),
            WasmInstr::Return,
            WasmInstr::End,
        ]);
    }
    body.extend([
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::Call("$set_new".to_owned()),
        WasmInstr::LocalSet(result),
    ]);

    match symbol {
        "$set_union" => {
            push_set_copy_loop(
                &mut body, 0, result, base, len, i, entry_base, value, "$done", "$scan", None,
            );
            push_set_copy_loop(
                &mut body, 1, result, base, len, i, entry_base, value, "$done2", "$scan2", None,
            );
        }
        "$set_intersection" => push_set_copy_loop(
            &mut body,
            0,
            result,
            base,
            len,
            i,
            entry_base,
            value,
            "$done",
            "$scan",
            Some((1, ValueTag::TRUE)),
        ),
        "$set_difference" => push_set_copy_loop(
            &mut body,
            0,
            result,
            base,
            len,
            i,
            entry_base,
            value,
            "$done",
            "$scan",
            Some((1, ValueTag::FALSE)),
        ),
        "$set_symmetric_difference" => {
            push_set_copy_loop(
                &mut body,
                0,
                result,
                base,
                len,
                i,
                entry_base,
                value,
                "$done",
                "$scan",
                Some((1, ValueTag::FALSE)),
            );
            push_set_copy_loop(
                &mut body,
                1,
                result,
                base,
                len,
                i,
                entry_base,
                value,
                "$done2",
                "$scan2",
                Some((0, ValueTag::FALSE)),
            );
        }
        _ => unreachable!("unsupported set algebra builder"),
    }

    body.push(WasmInstr::LocalGet(result));

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // base
        .local(WasmValType::I32) // len
        .local(WasmValType::I32) // i
        .local(WasmValType::I32) // entry_base
        .local(WasmValType::I32) // value
        .local(WasmValType::I32) // result
        .local(WasmValType::I32) // tag
        .body(body)
}

