fn push_two_element_pair_init(
    body: &mut Vec<WasmInstr>,
    pair_base: usize,
    first_value: Vec<WasmInstr>,
    second_value: Vec<WasmInstr>,
) {
    let array_header = Layout::ARRAY_HEADER_SIZE as i32;
    let array_capacity_offset = Layout::ARRAY_CAPACITY_OFFSET as i32;
    let array_presence_word_count_offset = Layout::ARRAY_PRESENCE_WORD_COUNT_OFFSET as i32;
    let array_elements_offset_offset = Layout::ARRAY_ELEMENTS_OFFSET_OFFSET as i32;
    let array_presence_words_offset = Layout::ARRAY_PRESENCE_WORDS_OFFSET as i32;

    body.extend([
        WasmInstr::I32Const(array_header),
        WasmInstr::I32Const(8),
        WasmInstr::I32Add,
        WasmInstr::Call("$alloc_heap".to_owned()),
        WasmInstr::LocalSet(pair_base),
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(2),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(array_capacity_offset),
        WasmInstr::I32Add,
        WasmInstr::I32Const(2),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(array_presence_word_count_offset),
        WasmInstr::I32Add,
        WasmInstr::I32Const(1),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(array_elements_offset_offset),
        WasmInstr::I32Add,
        WasmInstr::I32Const(array_header),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(array_presence_words_offset),
        WasmInstr::I32Add,
        WasmInstr::I32Const(3),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(array_header),
        WasmInstr::I32Add,
    ]);
    body.extend(first_value);
    body.extend([
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(array_header + 4),
        WasmInstr::I32Add,
    ]);
    body.extend(second_value);
    body.push(WasmInstr::I32Store {
        align: 2,
        offset: 0,
    });
}

fn build_entry_pairs_array(symbol: &str, second_value_offset: u32) -> WasmFunction {
    let collection_base = 2;
    let len = 3;
    let i = 4;
    let entry_base = 5;
    let array_base = 6;
    let result_len = 7;
    let pair_base = 8;
    let mut body = vec![];
    push_collection_to_array_prefix(
        &mut body,
        collection_base,
        len,
        result_len,
        array_base,
        false,
    );
    body.extend([
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::LocalSet(i),
        WasmInstr::Block("$done".to_owned()),
        WasmInstr::Loop("$copy".to_owned()),
        WasmInstr::LocalGet(i),
        WasmInstr::LocalGet(len),
        WasmInstr::I32GeU,
        WasmInstr::BrIf("$done".to_owned()),
    ]);
    body.extend(collection_entry_addr(collection_base, i));
    body.push(WasmInstr::LocalSet(entry_base));
    push_two_element_pair_init(
        &mut body,
        pair_base,
        vec![
            WasmInstr::LocalGet(entry_base),
            WasmInstr::I32Load {
                align: 2,
                offset: 0,
            },
        ],
        vec![
            WasmInstr::LocalGet(entry_base),
            WasmInstr::I32Load {
                align: 2,
                offset: second_value_offset,
            },
        ],
    );
    push_array_element_addr(&mut body, array_base, i);
    body.extend([
        WasmInstr::LocalGet(pair_base),
        WasmInstr::I32Const(ValueTag::ARRAY),
        WasmInstr::I32Or,
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(i),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(i),
        WasmInstr::Br("$copy".to_owned()),
        WasmInstr::End,
        WasmInstr::End,
        WasmInstr::LocalGet(array_base),
        WasmInstr::I32Const(ValueTag::ARRAY),
        WasmInstr::I32Or,
    ]);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // tag
        .local(WasmValType::I32) // collection_base
        .local(WasmValType::I32) // len
        .local(WasmValType::I32) // i
        .local(WasmValType::I32) // entry_base
        .local(WasmValType::I32) // array_base
        .local(WasmValType::I32) // result_len
        .local(WasmValType::I32) // pair_base
        .body(body)
}

