fn dataview_addr_prefix(
    dv: usize,
    offset: usize,
    elem_size: i32,
    first_local: usize,
    no_value_on_oob: bool,
) -> Vec<WasmInstr> {
    let heap_mask = ValueTag::HEAP_MASK;
    let array_header = Layout::ARRAY_HEADER_SIZE as i32;
    let num_shift = ValueTag::NUMBER_SHIFT;
    let dv_base = first_local;
    let byte_len = first_local + 1;
    let buf_base = first_local + 2;
    let vw_offset = first_local + 3;
    let arg_offset = first_local + 4;
    let addr = first_local + 5;
    let mut body = vec![
        WasmInstr::LocalGet(dv),
        WasmInstr::I32Const(heap_mask),
        WasmInstr::I32And,
        WasmInstr::LocalSet(dv_base),
        WasmInstr::LocalGet(dv_base),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(byte_len),
        WasmInstr::LocalGet(dv_base),
        WasmInstr::I32Const(4),
        WasmInstr::I32Add,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(buf_base),
        WasmInstr::LocalGet(dv_base),
        WasmInstr::I32Const(8),
        WasmInstr::I32Add,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(vw_offset),
        WasmInstr::LocalGet(offset),
        WasmInstr::I32Const(num_shift),
        WasmInstr::I32ShrS,
        WasmInstr::LocalSet(arg_offset),
        WasmInstr::LocalGet(arg_offset),
        WasmInstr::I32Const(elem_size),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(byte_len),
        WasmInstr::I32GtU,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ];
    if no_value_on_oob {
        body.push(WasmInstr::Return);
    } else {
        body.extend([WasmInstr::I32Const(RuntimeConst::ZERO), WasmInstr::Return]);
    }
    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(buf_base),
        WasmInstr::I32Const(array_header),
        WasmInstr::LocalGet(vw_offset),
        WasmInstr::LocalGet(arg_offset),
        WasmInstr::I32Add,
        WasmInstr::I32Add,
        WasmInstr::I32Add,
        WasmInstr::LocalSet(addr),
    ]);
    body
}

fn load_dataview_byte(addr: usize, offset: i32, target: usize) -> Vec<WasmInstr> {
    let mut body = vec![WasmInstr::LocalGet(addr)];
    if offset != 0 {
        body.extend([WasmInstr::I32Const(offset), WasmInstr::I32Add]);
    }
    body.extend([
        WasmInstr::I32Load8U {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalSet(target),
    ]);
    body
}

fn store_dataview_byte(addr: usize, offset: i32, raw: usize, shift: i32) -> Vec<WasmInstr> {
    let mut body = vec![WasmInstr::LocalGet(addr)];
    if offset != 0 {
        body.extend([WasmInstr::I32Const(offset), WasmInstr::I32Add]);
    }
    body.push(WasmInstr::LocalGet(raw));
    if shift != 0 {
        body.extend([WasmInstr::I32Const(shift), WasmInstr::I32ShrU]);
    }
    body.push(WasmInstr::I32Store8 {
        align: 0,
        offset: 0,
    });
    body
}

fn build_dataview_get_i16(symbol: &str, signed: bool) -> WasmFunction {
    let first_local = 3;
    let addr = first_local + 5;
    let b0 = first_local + 6;
    let b1 = first_local + 7;
    let value = first_local + 8;
    let mut body = dataview_addr_prefix(0, 1, 2, first_local, false);
    body.extend(load_dataview_byte(addr, 0, b0));
    body.extend(load_dataview_byte(addr, 1, b1));
    body.extend([
        WasmInstr::LocalGet(2),
        WasmInstr::I32Const(ValueTag::TRUE),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(b0),
        WasmInstr::LocalGet(b1),
        WasmInstr::I32Const(8),
        WasmInstr::I32Shl,
        WasmInstr::I32Or,
        WasmInstr::LocalSet(value),
        WasmInstr::Else,
        WasmInstr::LocalGet(b0),
        WasmInstr::I32Const(8),
        WasmInstr::I32Shl,
        WasmInstr::LocalGet(b1),
        WasmInstr::I32Or,
        WasmInstr::LocalSet(value),
        WasmInstr::End,
    ]);
    if signed {
        body.extend([
            WasmInstr::LocalGet(value),
            WasmInstr::I32Const(32768),
            WasmInstr::I32GeU,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(value),
            WasmInstr::I32Const(65536),
            WasmInstr::I32Sub,
            WasmInstr::LocalSet(value),
            WasmInstr::End,
        ]);
    }
    body.extend([
        WasmInstr::LocalGet(value),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32Shl,
        WasmInstr::I32Const(ValueTag::NUMBER),
        WasmInstr::I32Or,
    ]);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

