    if elem_size == 2 {
        body.extend(store_dataview_byte(addr, 0, raw, 0));
        body.extend(store_dataview_byte(addr, 1, raw, 8));
        body.push(WasmInstr::Else);
        body.extend(store_dataview_byte(addr, 0, raw, 8));
        body.extend(store_dataview_byte(addr, 1, raw, 0));
    } else {
        body.extend(store_dataview_byte(addr, 0, raw, 0));
        body.extend(store_dataview_byte(addr, 1, raw, 8));
        body.extend(store_dataview_byte(addr, 2, raw, 16));
        body.extend(store_dataview_byte(addr, 3, raw, 24));
        body.push(WasmInstr::Else);
        body.extend(store_dataview_byte(addr, 0, raw, 24));
        body.extend(store_dataview_byte(addr, 1, raw, 16));
        body.extend(store_dataview_byte(addr, 2, raw, 8));
        body.extend(store_dataview_byte(addr, 3, raw, 0));
    }
    body.push(WasmInstr::End);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
