fn push_store_dataview_i64_byte(
    body: &mut Vec<WasmInstr>,
    addr: usize,
    offset: i32,
    raw: usize,
    shift: i64,
) {
    let mut addr_instrs = vec![WasmInstr::LocalGet(addr)];
    if offset != 0 {
        addr_instrs.extend([WasmInstr::I32Const(offset), WasmInstr::I32Add]);
    }
    body.extend(addr_instrs);
    body.push(WasmInstr::LocalGet(raw));
    if shift != 0 {
        body.extend([WasmInstr::I64Const(shift), WasmInstr::I64ShrU]);
    }
    body.extend([
        WasmInstr::I32WrapI64,
        WasmInstr::I32Store8 {
            align: 0,
            offset: 0,
        },
    ]);
}

fn build_dataview_set_bigint(symbol: &str) -> WasmFunction {
    let first_local = 4;
    let addr = first_local + 5;
    let big = first_local + 6;
    let raw = first_local + 7;
    let mut body = dataview_addr_prefix(0, 1, 8, first_local, true);
    body.extend([
        WasmInstr::LocalGet(2),
        WasmInstr::Call("$bigint_from_value".to_owned()),
        WasmInstr::LocalSet(big),
        WasmInstr::LocalGet(big),
        WasmInstr::Call("$bigint_signed_i64".to_owned()),
        WasmInstr::LocalSet(raw),
        WasmInstr::LocalGet(3),
        WasmInstr::I32Const(ValueTag::TRUE),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    for (offset, shift) in [0, 8, 16, 24, 32, 40, 48, 56].into_iter().enumerate() {
        push_store_dataview_i64_byte(&mut body, addr, offset as i32, raw, shift);
    }
    body.push(WasmInstr::Else);
    for (offset, shift) in [56, 48, 40, 32, 24, 16, 8, 0].into_iter().enumerate() {
        push_store_dataview_i64_byte(&mut body, addr, offset as i32, raw, shift);
    }
    body.push(WasmInstr::End);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I64)
        .body(body)
}

