fn build_atomics_drop_args_number_zero(symbol: &str, params: usize) -> WasmFunction {
    let mut function = WasmFunction::new(symbol);
    let mut body = Vec::with_capacity(params * 2 + 1);
    for index in 0..params {
        function = function.param(WasmValType::I32);
        body.push(WasmInstr::LocalGet(index));
        body.push(WasmInstr::Drop);
    }
    body.push(WasmInstr::I32Const(ValueTag::NUMBER));
    function.result(WasmValType::I32).body(body)
}

