/// Build the private `$bigint_compare_small_int` helper emitted with
/// relational comparisons.
///
/// Returns `-1`, `0`, or `1` by comparing a BigInt against an i32.
/// Remaining raw escape hatches: none.
pub fn build_bigint_compare_small_int() -> WasmFunction {
    let heap_mask = ValueTag::HEAP_MASK;
    let sign_offset = Layout::BIGINT_SIGN_OFFSET as i32;
    let limb0_high_offset = Layout::BIGINT_LIMB0_HIGH_OFFSET as u32;
    let limb0_low_offset = Layout::BIGINT_LIMB0_LOW_OFFSET as u32;

    WasmFunction::new("$bigint_compare_small_int")
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 2: obj
        .local(WasmValType::I32) // local 3: sign
        .local(WasmValType::I32) // local 4: expected_sign
        .local(WasmValType::I32) // local 5: abs
        .local(WasmValType::I32) // local 6: low
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(heap_mask),
            WasmInstr::I32And,
            WasmInstr::LocalSet(2),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(sign_offset),
            WasmInstr::I32Add,
            WasmInstr::I32Load {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalSet(3),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(3),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32LtS,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(-1),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(3),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32LtS,
            WasmInstr::If {
                result_ty: WasmBlockType::Result(WasmValType::I32),
            },
            WasmInstr::Then,
            WasmInstr::I32Const(-1),
            WasmInstr::Else,
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::End,
            WasmInstr::LocalSet(4),
            WasmInstr::LocalGet(3),
            WasmInstr::LocalGet(4),
            WasmInstr::I32LtS,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(-1),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(3),
            WasmInstr::LocalGet(4),
            WasmInstr::I32GtS,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32LtS,
            WasmInstr::If {
                result_ty: WasmBlockType::Result(WasmValType::I32),
            },
            WasmInstr::Then,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Sub,
            WasmInstr::Else,
            WasmInstr::LocalGet(1),
            WasmInstr::End,
            WasmInstr::LocalSet(5),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Load {
                align: 2,
                offset: limb0_high_offset,
            },
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Ne,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(3),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(2),
            WasmInstr::I32Load {
                align: 2,
                offset: limb0_low_offset,
            },
            WasmInstr::LocalSet(6),
            WasmInstr::LocalGet(6),
            WasmInstr::LocalGet(5),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(6),
            WasmInstr::LocalGet(5),
            WasmInstr::I32LtU,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(3),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32LtS,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::I32Const(-1),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(3),
        ])
}

#[derive(Clone, Copy)]
enum RelOp {
    Less,
    LessEqual,
    Greater,
    GreaterEqual,
}

impl RelOp {
    fn name(self) -> &'static str {
        match self {
            Self::Less => "less",
            Self::LessEqual => "less_equal",
            Self::Greater => "greater",
            Self::GreaterEqual => "greater_equal",
        }
    }

    fn compare_instr(self) -> WasmInstr {
        match self {
            Self::Less => WasmInstr::I32LtS,
            Self::LessEqual => WasmInstr::I32LeS,
            Self::Greater => WasmInstr::I32GtS,
            Self::GreaterEqual => WasmInstr::I32GeS,
        }
    }

    fn inverted(self) -> Self {
        match self {
            Self::Less => Self::Greater,
            Self::LessEqual => Self::GreaterEqual,
            Self::Greater => Self::Less,
            Self::GreaterEqual => Self::LessEqual,
        }
    }
}

fn append_rel_condition_to_tagged_bool(body: &mut Vec<WasmInstr>) {
    body.extend([
        WasmInstr::If {
            result_ty: WasmBlockType::Result(WasmValType::I32),
        },
        WasmInstr::Then,
        WasmInstr::I32Const(ValueTag::TRUE),
        WasmInstr::Else,
        WasmInstr::I32Const(ValueTag::FALSE),
        WasmInstr::End,
    ]);
}

fn append_rel_compare_zero(body: &mut Vec<WasmInstr>, op: RelOp) {
    body.extend([WasmInstr::I32Const(RuntimeConst::ZERO), op.compare_instr()]);
    append_rel_condition_to_tagged_bool(body);
}

fn append_rel_bigint_string_branch(
    body: &mut Vec<WasmInstr>,
    op: RelOp,
    bigint_local: usize,
    string_local: usize,
    string_tag_local: usize,
    invert_compare: bool,
) {
    let compare_op = if invert_compare { op.inverted() } else { op };

    body.extend([
        WasmInstr::LocalGet(bigint_local),
        WasmInstr::Call("$is_bigint".to_owned()),
        WasmInstr::LocalGet(string_tag_local),
        WasmInstr::I32Const(ValueTag::STRING),
        WasmInstr::I32Eq,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(bigint_local),
        WasmInstr::LocalGet(string_local),
        WasmInstr::Call("$bigint_compare_decimal_string_for_relational".to_owned()),
        WasmInstr::LocalSet(4),
        WasmInstr::LocalGet(4),
        WasmInstr::I32Const(-2),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(ValueTag::FALSE),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(4),
        WasmInstr::I32Const(-3),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(string_local),
        WasmInstr::Call("$bigint_string_to_small_int_for_comparison".to_owned()),
        WasmInstr::LocalSet(4),
        WasmInstr::LocalGet(4),
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(ValueTag::FALSE),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(bigint_local),
        WasmInstr::LocalGet(4),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32ShrS,
        WasmInstr::Call("$bigint_compare_small_int".to_owned()),
        WasmInstr::LocalSet(4),
        WasmInstr::End,
        WasmInstr::LocalGet(4),
    ]);
    append_rel_compare_zero(body, compare_op);
    body.extend([WasmInstr::Return, WasmInstr::End]);
}

fn append_rel_bigint_bool_branch(
    body: &mut Vec<WasmInstr>,
    op: RelOp,
    bigint_local: usize,
    bool_local: usize,
    invert_compare: bool,
) {
    let compare_op = if invert_compare { op.inverted() } else { op };

    body.extend([
        WasmInstr::LocalGet(bigint_local),
        WasmInstr::Call("$is_bigint".to_owned()),
        WasmInstr::LocalGet(bool_local),
        WasmInstr::I32Const(ValueTag::FALSE),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(bool_local),
        WasmInstr::I32Const(ValueTag::TRUE),
        WasmInstr::I32Eq,
        WasmInstr::I32Or,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(bigint_local),
        WasmInstr::LocalGet(bool_local),
        WasmInstr::I32Const(ValueTag::TRUE),
        WasmInstr::I32Eq,
        WasmInstr::Call("$bigint_compare_small_int".to_owned()),
    ]);
    append_rel_compare_zero(body, compare_op);
    body.extend([WasmInstr::Return, WasmInstr::End]);
}

fn append_rel_bigint_number_branch(
    body: &mut Vec<WasmInstr>,
    op: RelOp,
    bigint_local: usize,
    number_local: usize,
    number_tag_local: usize,
    invert_compare: bool,
) {
    let compare_op = if invert_compare { op.inverted() } else { op };

    body.extend([
        WasmInstr::LocalGet(bigint_local),
        WasmInstr::Call("$is_bigint".to_owned()),
        WasmInstr::LocalGet(number_tag_local),
        WasmInstr::I32Const(ValueTag::NUMBER),
        WasmInstr::I32Eq,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(bigint_local),
        WasmInstr::LocalGet(number_local),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32ShrS,
        WasmInstr::Call("$bigint_compare_small_int".to_owned()),
    ]);
    append_rel_compare_zero(body, compare_op);
    body.extend([WasmInstr::Return, WasmInstr::End]);
}

fn build_relational_compare(op: RelOp) -> WasmFunction {
    let symbol = format!("${}", op.name());
    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(2),
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(3),
        WasmInstr::LocalGet(0),
        WasmInstr::Call("$is_bigint".to_owned()),
        WasmInstr::LocalGet(1),
        WasmInstr::Call("$is_bigint".to_owned()),
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(0),
        WasmInstr::LocalGet(1),
        WasmInstr::Call("$bigint_compare".to_owned()),
    ];
    append_rel_compare_zero(&mut body, op);
    body.extend([WasmInstr::Return, WasmInstr::End]);

    append_rel_bigint_string_branch(&mut body, op, 0, 1, 3, false);
    append_rel_bigint_string_branch(&mut body, op, 1, 0, 2, true);
    append_rel_bigint_bool_branch(&mut body, op, 0, 1, false);
    append_rel_bigint_bool_branch(&mut body, op, 1, 0, true);
    append_rel_bigint_number_branch(&mut body, op, 0, 1, 3, false);
    append_rel_bigint_number_branch(&mut body, op, 1, 0, 2, true);

    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::Call("$is_bigint".to_owned()),
        WasmInstr::LocalGet(1),
        WasmInstr::Call("$is_bigint".to_owned()),
        WasmInstr::I32Or,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::Unreachable,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
        WasmInstr::Call("$number_to_i32".to_owned()),
        WasmInstr::LocalGet(1),
        WasmInstr::Call("$number_to_i32".to_owned()),
        op.compare_instr(),
    ]);
    append_rel_condition_to_tagged_bool(&mut body);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 2: a_tag
        .local(WasmValType::I32) // local 3: b_tag
        .local(WasmValType::I32) // local 4: n
        .body(body)
}

fn build_relational_fast(symbol: &str, target: &str, op: RelOp) -> WasmFunction {
    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::TAG_MASK),
            WasmInstr::I32And,
            WasmInstr::I32Const(ValueTag::NUMBER),
            WasmInstr::I32Eq,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::TAG_MASK),
            WasmInstr::I32And,
            WasmInstr::I32Const(ValueTag::NUMBER),
            WasmInstr::I32Eq,
            WasmInstr::I32And,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
            WasmInstr::I32ShrS,
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
            WasmInstr::I32ShrS,
            op.compare_instr(),
            WasmInstr::If {
                result_ty: WasmBlockType::Result(WasmValType::I32),
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::TRUE),
            WasmInstr::Else,
            WasmInstr::I32Const(ValueTag::FALSE),
            WasmInstr::End,
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::LocalGet(1),
            WasmInstr::Call(target.to_owned()),
        ])
}

