fn append_load_string_byte(body: &mut Vec<WasmInstr>, ptr: usize, index: usize, target: usize) {
    body.extend([
        WasmInstr::LocalGet(ptr),
        WasmInstr::LocalGet(index),
        WasmInstr::I32Add,
        WasmInstr::I32Load8U {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalSet(target),
    ]);
}

fn append_ascii_whitespace_test(body: &mut Vec<WasmInstr>, ch: usize) {
    body.extend([
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(32),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(9),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(10),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(13),
        WasmInstr::I32Eq,
        WasmInstr::I32Or,
        WasmInstr::I32Or,
        WasmInstr::I32Or,
    ]);
}

fn append_ascii_digit_decode(body: &mut Vec<WasmInstr>, ch: usize, digit: usize) {
    body.extend([
        WasmInstr::I32Const(-1),
        WasmInstr::LocalSet(digit),
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(RuntimeConst::ASCII_ZERO),
        WasmInstr::I32GeU,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(57),
        WasmInstr::I32LeU,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(RuntimeConst::ASCII_ZERO),
        WasmInstr::I32Sub,
        WasmInstr::LocalSet(digit),
        WasmInstr::Else,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(97),
        WasmInstr::I32GeU,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(102),
        WasmInstr::I32LeU,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(97),
        WasmInstr::I32Sub,
        WasmInstr::I32Const(RuntimeConst::TEN),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(digit),
        WasmInstr::Else,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(65),
        WasmInstr::I32GeU,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(70),
        WasmInstr::I32LeU,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(ch),
        WasmInstr::I32Const(65),
        WasmInstr::I32Sub,
        WasmInstr::I32Const(RuntimeConst::TEN),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(digit),
        WasmInstr::End,
        WasmInstr::End,
        WasmInstr::End,
    ]);
}

fn append_compare_bigint_to_zero(body: &mut Vec<WasmInstr>) {
    body.extend([
        WasmInstr::LocalGet(2),
        WasmInstr::I32Const(Layout::BIGINT_SIGN_OFFSET as i32),
        WasmInstr::I32Add,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(13),
        WasmInstr::LocalGet(13),
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::I32LtS,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(-1),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(13),
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::I32GtS,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::Return,
    ]);
}

/// Build the private `$bigint_compare_decimal_string_for_relational` helper.
