fn push_object_entry_addr(body: &mut Vec<WasmInstr>, object_base: usize, index: usize) {
    body.extend([
        WasmInstr::LocalGet(object_base),
        WasmInstr::I32Const(Layout::OBJECT_HEADER_SIZE as i32),
        WasmInstr::LocalGet(index),
        WasmInstr::I32Const(Layout::OBJECT_ENTRY_SHIFT as i32),
        WasmInstr::I32Shl,
        WasmInstr::I32Add,
        WasmInstr::I32Add,
    ]);
}

fn push_store_key_to_array(body: &mut Vec<WasmInstr>, array_base: usize, index: usize, key: usize) {
    push_array_element_addr(body, array_base, index);
    body.extend([
        WasmInstr::LocalGet(key),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(index),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(index),
    ]);
}

