fn build_promise_with_state(symbol: &str, value_param: Option<usize>, state: i32) -> WasmFunction {
    let base = if value_param.is_some() { 1 } else { 0 };
    let mut function = WasmFunction::new(symbol).result(WasmValType::I32);
    if value_param.is_some() {
        function = function.param(WasmValType::I32);
    }

    function.local(WasmValType::I32).body(vec![
        WasmInstr::I32Const((Layout::ARRAY_HEADER_SIZE + 16) as i32),
        WasmInstr::Call("$alloc_heap".to_owned()),
        WasmInstr::LocalSet(base),
        WasmInstr::LocalGet(base),
        WasmInstr::I32Const(4),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(base),
        WasmInstr::I32Const(state),
        WasmInstr::I32Store {
            align: 2,
            offset: Layout::ARRAY_HEADER_SIZE,
        },
        WasmInstr::LocalGet(base),
        value_param
            .map(WasmInstr::LocalGet)
            .unwrap_or(WasmInstr::I32Const(ValueTag::UNDEFINED)),
        WasmInstr::I32Store {
            align: 2,
            offset: Layout::ARRAY_HEADER_SIZE + 4,
        },
        WasmInstr::LocalGet(base),
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::I32Store {
            align: 2,
            offset: Layout::ARRAY_HEADER_SIZE + 8,
        },
        WasmInstr::LocalGet(base),
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::I32Store {
            align: 2,
            offset: Layout::ARRAY_HEADER_SIZE + 12,
        },
        WasmInstr::LocalGet(base),
        WasmInstr::I32Const(ValueTag::ARRAY),
        WasmInstr::I32Or,
    ])
}

