fn append_math_number_guard(body: &mut Vec<WasmInstr>) {
    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(1),
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::NUMBER),
        WasmInstr::I32Eq,
        WasmInstr::LocalSet(3),
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::OBJECT),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(2),
        WasmInstr::LocalGet(2),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::I32Const(Layout::HEAP_NUMBER_SENTINEL),
        WasmInstr::I32Eq,
        WasmInstr::LocalSet(3),
        WasmInstr::End,
        WasmInstr::LocalGet(3),
        WasmInstr::I32Eqz,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(tagged_number_sentinel(ValueTag::NAN_PAYLOAD)),
        WasmInstr::Return,
        WasmInstr::End,
    ]);
}

fn build_math_integral_identity(symbol: &str) -> WasmFunction {
    let mut body = Vec::new();
    append_math_number_guard(&mut body);
    body.push(WasmInstr::LocalGet(0));

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // tag
        .local(WasmValType::I32) // heap number object pointer
        .local(WasmValType::I32) // is_number
        .body(body)
}

fn build_math_host_unary(symbol: &str, host_symbol: &str) -> WasmFunction {
    let mut body = Vec::new();
    append_math_number_guard(&mut body);
    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::Call(host_symbol.to_owned()),
        WasmInstr::Return,
    ]);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // tag
        .local(WasmValType::I32) // heap number object pointer
        .local(WasmValType::I32) // is_number
        .body(body)
}

