fn build_math_host_binary(symbol: &str, host_symbol: &str) -> WasmFunction {
    let mut body = Vec::new();
    append_math_binary_host_number_guard(&mut body);
    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::LocalGet(1),
        WasmInstr::Call(host_symbol.to_owned()),
        WasmInstr::Return,
    ]);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // first tag
        .local(WasmValType::I32) // second tag
        .local(WasmValType::I32) // heap number object pointer
        .local(WasmValType::I32) // first is_number
        .local(WasmValType::I32) // second is_number
        .body(body)
}

/// Build the `$math_floor` function.
///
/// The current number model stores integer-backed values exactly, so floor is
/// a no-op after the legacy numeric guard accepts tagged or heap numbers.
/// Remaining raw escape hatches: none.
pub fn build_math_floor() -> WasmFunction {
    build_math_integral_identity("$math_floor")
}

