/// Remaining raw escape hatches: none.
pub fn build_property_has() -> WasmFunction {
    let tag_mask = ValueTag::TAG_MASK;
    let object_tag = ValueTag::OBJECT;
    let heap_mask = ValueTag::HEAP_MASK;
    let object_header = Layout::OBJECT_HEADER_SIZE as i32;
    let object_proto = Layout::OBJECT_PROTOTYPE_OFFSET as u32;
    let object_entry_shift = Layout::OBJECT_ENTRY_SHIFT as i32;
    let string_header = Layout::STRING_HEADER_SIZE as i32;
    let symbol_sentinel = Layout::SYMBOL_SENTINEL;

    WasmFunction::new("$property_has")
        .param(WasmValType::I32) // local 0: object
        .param(WasmValType::I32) // local 1: key_ptr or symbol value
        .param(WasmValType::I32) // local 2: key_len or -1
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 3: tag
        .local(WasmValType::I32) // local 4: base
        .local(WasmValType::I32) // local 5: proto
        .local(WasmValType::I32) // local 6: count
        .local(WasmValType::I32) // local 7: i
        .local(WasmValType::I32) // local 8: steps
        .local(WasmValType::I32) // local 9: entry_base
        .local(WasmValType::I32) // local 10: pk_raw
        .local(WasmValType::I32) // local 11: pk_ptr
        .local(WasmValType::I32) // local 12: pk_len
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(tag_mask),
            WasmInstr::I32And,
            WasmInstr::LocalSet(3),
            WasmInstr::LocalGet(3),
            WasmInstr::I32Const(object_tag),
            WasmInstr::I32Ne,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::FALSE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(heap_mask),
            WasmInstr::I32And,
            WasmInstr::LocalSet(4),
            WasmInstr::Block("$walk_done".to_owned()),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::LocalSet(8),
            WasmInstr::Loop("$walk".to_owned()),
            WasmInstr::LocalGet(4),
            WasmInstr::I32Load {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalSet(6),
            WasmInstr::LocalGet(6),
            WasmInstr::LocalSet(7),
            WasmInstr::Block("$scan_done".to_owned()),
            WasmInstr::Loop("$scan_entries".to_owned()),
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32Eq,
            WasmInstr::BrIf("$scan_done".to_owned()),
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::I32Sub,
            WasmInstr::LocalSet(7),
            WasmInstr::LocalGet(4),
            WasmInstr::I32Const(object_header),
            WasmInstr::LocalGet(7),
            WasmInstr::I32Const(object_entry_shift),
            WasmInstr::I32Shl,
            WasmInstr::I32Add,
            WasmInstr::I32Add,
            WasmInstr::LocalSet(9),
            WasmInstr::LocalGet(9),
            WasmInstr::I32Load {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalSet(10),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(-1),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::LocalGet(10),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::TRUE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::Br("$scan_entries".to_owned()),
            WasmInstr::End,
            WasmInstr::LocalGet(10),
            WasmInstr::I32Const(tag_mask),
            WasmInstr::I32And,
            WasmInstr::I32Const(object_tag),
            WasmInstr::I32Eq,
            WasmInstr::LocalGet(10),
            WasmInstr::I32Const(heap_mask),
            WasmInstr::I32And,
            WasmInstr::I32Load {
                align: 2,
                offset: 0,
            },
            WasmInstr::I32Const(symbol_sentinel),
            WasmInstr::I32Eq,
            WasmInstr::I32And,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::Br("$scan_entries".to_owned()),
            WasmInstr::End,
            WasmInstr::LocalGet(10),
            WasmInstr::I32Const(heap_mask),
            WasmInstr::I32And,
            WasmInstr::I32Const(string_header),
            WasmInstr::I32Add,
            WasmInstr::LocalSet(11),
            WasmInstr::LocalGet(10),
            WasmInstr::I32Const(heap_mask),
            WasmInstr::I32And,
            WasmInstr::I32Load {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalSet(12),
            WasmInstr::LocalGet(2),
            WasmInstr::LocalGet(12),
            WasmInstr::I32Ne,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::Br("$scan_entries".to_owned()),
            WasmInstr::End,
            WasmInstr::LocalGet(1),
            WasmInstr::LocalGet(11),
            WasmInstr::LocalGet(2),
            WasmInstr::Call("$mem_equal".to_owned()),
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::TRUE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::Br("$scan_entries".to_owned()),
            WasmInstr::End,
            WasmInstr::End,
            WasmInstr::LocalGet(4),
            WasmInstr::I32Load {
                align: 2,
                offset: object_proto,
            },
            WasmInstr::LocalSet(5),
            WasmInstr::LocalGet(5),
            WasmInstr::I32Eqz,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::FALSE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(4),
            WasmInstr::LocalGet(5),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::FALSE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(8),
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::I32Add,
            WasmInstr::LocalSet(8),
            WasmInstr::LocalGet(8),
            WasmInstr::I32Const(64),
            WasmInstr::I32GeU,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(ValueTag::FALSE),
            WasmInstr::Return,
            WasmInstr::End,
            WasmInstr::LocalGet(5),
            WasmInstr::LocalSet(4),
            WasmInstr::Br("$walk".to_owned()),
            WasmInstr::End,
            WasmInstr::End,
            WasmInstr::I32Const(ValueTag::FALSE),
        ])
}

/// Build the `$property_get` function.
///
/// Walks array/object property storage for string keys and symbol keys. The
/// caller supplies either `(key_ptr, key_len)` for string keys or
/// `(symbol_value, -1)` for symbol keys.
/// Remaining raw escape hatches: none.
pub fn build_property_get(data: PropertyGetData) -> WasmFunction {
    let tag_mask = ValueTag::TAG_MASK;
    let number_tag = ValueTag::NUMBER;
    let number_shift = ValueTag::NUMBER_SHIFT;
    let direct_local_token_payload_base = ValueTag::DIRECT_LOCAL_TOKEN_PAYLOAD_BASE;
    let object_tag = ValueTag::OBJECT;
    let array_tag = ValueTag::ARRAY;
    let heap_mask = ValueTag::HEAP_MASK;
    let object_header = Layout::OBJECT_HEADER_SIZE as i32;
    let object_proto = Layout::OBJECT_PROTOTYPE_OFFSET as u32;
    let object_entry_shift = Layout::OBJECT_ENTRY_SHIFT as i32;
    let object_value_offset = Layout::OBJECT_VALUE_OFFSET as u32;
    let array_header = Layout::ARRAY_HEADER_SIZE as i32;
    let array_capacity_offset = Layout::ARRAY_CAPACITY_OFFSET as u32;
    let array_presence_words_offset = Layout::ARRAY_PRESENCE_WORDS_OFFSET as u32;
    let string_header = Layout::STRING_HEADER_SIZE as i32;
    let symbol_sentinel = Layout::SYMBOL_SENTINEL;
    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(tag_mask),
        WasmInstr::I32And,
        WasmInstr::LocalSet(3),
        // Direct-local function tokens are NUMBER-tagged sentinels that expose
        // reflective `name` and `length` properties.
        WasmInstr::LocalGet(3),
        WasmInstr::I32Const(number_tag),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(number_shift),
        WasmInstr::I32ShrU,
        WasmInstr::LocalSet(17),
        WasmInstr::LocalGet(17),
        WasmInstr::I32Const(direct_local_token_payload_base),
        WasmInstr::I32GeU,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(2),
        WasmInstr::I32Const(data.name_key.len),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(data.name_key.ptr),
        WasmInstr::LocalGet(2),
        WasmInstr::Call("$mem_equal".to_owned()),
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ];

    for function in data
        .direct_functions
        .iter()
        .filter(|function| function.name_value.is_some())
    {
        body.extend([
            WasmInstr::LocalGet(17),
            WasmInstr::I32Const(function.payload),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(function.name_value.expect("filtered by name_value")),
            WasmInstr::Return,
            WasmInstr::End,
        ]);
    }

    body.extend([
        WasmInstr::End,
        WasmInstr::LocalGet(2),
        WasmInstr::I32Const(data.length_key.len),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(data.length_key.ptr),
        WasmInstr::LocalGet(2),
        WasmInstr::Call("$mem_equal".to_owned()),
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);

    for function in &data.direct_functions {
        body.extend([
            WasmInstr::LocalGet(17),
            WasmInstr::I32Const(function.payload),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(function.length_value),
            WasmInstr::Return,
            WasmInstr::End,
        ]);
    }

    body.extend([
        WasmInstr::End,
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::End,
    ]);

    WasmFunction::new("$property_get")
        .param(WasmValType::I32) // local 0: object
        .param(WasmValType::I32) // local 1: key_ptr or symbol value
        .param(WasmValType::I32) // local 2: key_len or -1
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 3: tag
        .local(WasmValType::I32) // local 4: base
        .local(WasmValType::I32) // local 5: proto
        .local(WasmValType::I32) // local 6: count
        .local(WasmValType::I32) // local 7: i
        .local(WasmValType::I32) // local 8: steps
        .local(WasmValType::I32) // local 9: entry_base
        .local(WasmValType::I32) // local 10: pk_raw
        .local(WasmValType::I32) // local 11: pk_ptr
        .local(WasmValType::I32) // local 12: pk_len
        .local(WasmValType::I32) // local 13: digit
        .local(WasmValType::I32) // local 14: array_idx
        .local(WasmValType::I32) // local 15: is_array_index
        .local(WasmValType::I32) // local 16: array_steps
        .local(WasmValType::I32) // local 17: direct function payload
        .body({
            body.extend([
                // Array tag: parse the supplied string key as a dense numeric index.
                WasmInstr::LocalGet(3),
                WasmInstr::I32Const(array_tag),
                WasmInstr::I32Eq,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(RuntimeConst::ONE),
                WasmInstr::LocalSet(15),
                WasmInstr::I32Const(RuntimeConst::ZERO),
                WasmInstr::LocalSet(14),
                WasmInstr::LocalGet(2),
                WasmInstr::I32Eqz,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(RuntimeConst::ZERO),
                WasmInstr::LocalSet(15),
                WasmInstr::Else,
                WasmInstr::I32Const(RuntimeConst::ZERO),
                WasmInstr::LocalSet(7),
                WasmInstr::Block("$parse_done".to_owned()),
                WasmInstr::Loop("$parse".to_owned()),
                WasmInstr::LocalGet(7),
                WasmInstr::LocalGet(2),
                WasmInstr::I32GeU,
                WasmInstr::BrIf("$parse_done".to_owned()),
                WasmInstr::LocalGet(1),
                WasmInstr::LocalGet(7),
                WasmInstr::I32Add,
                WasmInstr::I32Load8U {
                    align: 0,
                    offset: 0,
                },
                WasmInstr::LocalSet(13),
                WasmInstr::LocalGet(13),
                WasmInstr::I32Const(48),
                WasmInstr::I32LtU,
                WasmInstr::LocalGet(13),
                WasmInstr::I32Const(57),
                WasmInstr::I32GtU,
                WasmInstr::I32Or,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(RuntimeConst::ZERO),
                WasmInstr::LocalSet(15),
                WasmInstr::Br("$parse_done".to_owned()),
                WasmInstr::End,
                WasmInstr::LocalGet(13),
                WasmInstr::I32Const(48),
                WasmInstr::I32Sub,
                WasmInstr::LocalSet(13),
                WasmInstr::LocalGet(14),
                WasmInstr::I32Const(10),
                WasmInstr::I32Mul,
                WasmInstr::LocalGet(13),
                WasmInstr::I32Add,
                WasmInstr::LocalSet(14),
                WasmInstr::LocalGet(7),
                WasmInstr::I32Const(RuntimeConst::ONE),
                WasmInstr::I32Add,
                WasmInstr::LocalSet(7),
                WasmInstr::Br("$parse".to_owned()),
                WasmInstr::End,
                WasmInstr::End,
                WasmInstr::End,
                WasmInstr::LocalGet(15),
                WasmInstr::I32Const(RuntimeConst::ZERO),
                WasmInstr::I32Ne,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::LocalGet(0),
                WasmInstr::I32Const(heap_mask),
                WasmInstr::I32And,
                WasmInstr::LocalSet(4),
                WasmInstr::Block("$array_forward_done".to_owned()),
                WasmInstr::Loop("$array_forward".to_owned()),
                WasmInstr::LocalGet(4),
                WasmInstr::I32Load {
                    align: 2,
                    offset: array_capacity_offset,
                },
                WasmInstr::I32Const(-1),
                WasmInstr::I32Ne,
                WasmInstr::BrIf("$array_forward_done".to_owned()),
                WasmInstr::LocalGet(16),
                WasmInstr::I32Const(RuntimeConst::ONE),
                WasmInstr::I32Add,
                WasmInstr::LocalSet(16),
                WasmInstr::LocalGet(16),
                WasmInstr::I32Const(64),
                WasmInstr::I32GtU,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::LocalGet(4),
                WasmInstr::I32Load {
                    align: 2,
                    offset: Layout::ARRAY_HEADER_SIZE as u32,
                },
                WasmInstr::I32Const(heap_mask),
                WasmInstr::I32And,
                WasmInstr::LocalSet(4),
                WasmInstr::Br("$array_forward".to_owned()),
                WasmInstr::End,
                WasmInstr::End,
                WasmInstr::LocalGet(14),
                WasmInstr::LocalGet(4),
                WasmInstr::I32Load {
                    align: 2,
                    offset: 0,
                },
                WasmInstr::I32GeU,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::LocalGet(4),
                WasmInstr::I32Load {
                    align: 2,
                    offset: array_presence_words_offset,
                },
                WasmInstr::I32Const(RuntimeConst::ONE),
                WasmInstr::LocalGet(14),
                WasmInstr::I32Shl,
                WasmInstr::I32And,
                WasmInstr::I32Eqz,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::LocalGet(4),
                WasmInstr::I32Const(array_header),
                WasmInstr::LocalGet(14),
                WasmInstr::I32Const(2),
                WasmInstr::I32Shl,
                WasmInstr::I32Add,
                WasmInstr::I32Add,
                WasmInstr::I32Load {
                    align: 2,
                    offset: 0,
                },
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                // Object tag: scan own entries, then walk the prototype chain.
                WasmInstr::LocalGet(3),
                WasmInstr::I32Const(object_tag),
                WasmInstr::I32Ne,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::LocalGet(0),
                WasmInstr::I32Const(heap_mask),
                WasmInstr::I32And,
                WasmInstr::LocalSet(4),
                WasmInstr::Block("$walk_done".to_owned()),
                WasmInstr::I32Const(RuntimeConst::ZERO),
                WasmInstr::LocalSet(8),
                WasmInstr::Loop("$walk".to_owned()),
                WasmInstr::LocalGet(4),
                WasmInstr::I32Load {
                    align: 2,
                    offset: 0,
                },
                WasmInstr::LocalSet(6),
                WasmInstr::LocalGet(6),
                WasmInstr::LocalSet(7),
                WasmInstr::Block("$scan_done".to_owned()),
                WasmInstr::Loop("$scan_entries".to_owned()),
                WasmInstr::LocalGet(7),
                WasmInstr::I32Const(RuntimeConst::ZERO),
                WasmInstr::I32Eq,
                WasmInstr::BrIf("$scan_done".to_owned()),
                WasmInstr::LocalGet(7),
                WasmInstr::I32Const(RuntimeConst::ONE),
                WasmInstr::I32Sub,
                WasmInstr::LocalSet(7),
                WasmInstr::LocalGet(4),
                WasmInstr::I32Const(object_header),
                WasmInstr::LocalGet(7),
                WasmInstr::I32Const(object_entry_shift),
                WasmInstr::I32Shl,
                WasmInstr::I32Add,
                WasmInstr::I32Add,
                WasmInstr::LocalSet(9),
                WasmInstr::LocalGet(9),
                WasmInstr::I32Load {
                    align: 2,
                    offset: 0,
                },
                WasmInstr::LocalSet(10),
                WasmInstr::LocalGet(2),
                WasmInstr::I32Const(-1),
                WasmInstr::I32Eq,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::LocalGet(10),
                WasmInstr::LocalGet(1),
                WasmInstr::I32Eq,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::LocalGet(9),
                WasmInstr::I32Load {
                    align: 2,
                    offset: object_value_offset,
                },
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::Br("$scan_entries".to_owned()),
                WasmInstr::End,
                WasmInstr::LocalGet(10),
                WasmInstr::I32Const(tag_mask),
                WasmInstr::I32And,
                WasmInstr::I32Const(object_tag),
                WasmInstr::I32Eq,
                WasmInstr::LocalGet(10),
                WasmInstr::I32Const(heap_mask),
                WasmInstr::I32And,
                WasmInstr::I32Load {
                    align: 2,
                    offset: 0,
                },
                WasmInstr::I32Const(symbol_sentinel),
                WasmInstr::I32Eq,
                WasmInstr::I32And,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::Br("$scan_entries".to_owned()),
                WasmInstr::End,
                WasmInstr::LocalGet(10),
                WasmInstr::I32Const(heap_mask),
                WasmInstr::I32And,
                WasmInstr::I32Const(string_header),
                WasmInstr::I32Add,
                WasmInstr::LocalSet(11),
                WasmInstr::LocalGet(10),
                WasmInstr::I32Const(heap_mask),
                WasmInstr::I32And,
                WasmInstr::I32Load {
                    align: 2,
                    offset: 0,
                },
                WasmInstr::LocalSet(12),
                WasmInstr::LocalGet(2),
                WasmInstr::LocalGet(12),
                WasmInstr::I32Ne,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::Br("$scan_entries".to_owned()),
                WasmInstr::End,
                WasmInstr::LocalGet(1),
                WasmInstr::LocalGet(11),
                WasmInstr::LocalGet(2),
                WasmInstr::Call("$mem_equal".to_owned()),
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::LocalGet(9),
                WasmInstr::I32Load {
                    align: 2,
                    offset: object_value_offset,
                },
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::Br("$scan_entries".to_owned()),
                WasmInstr::End,
                WasmInstr::End,
                WasmInstr::LocalGet(4),
                WasmInstr::I32Load {
                    align: 2,
                    offset: object_proto,
                },
                WasmInstr::LocalSet(5),
                WasmInstr::LocalGet(5),
                WasmInstr::I32Eqz,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::LocalGet(4),
                WasmInstr::LocalGet(5),
                WasmInstr::I32Eq,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::LocalGet(8),
                WasmInstr::I32Const(RuntimeConst::ONE),
                WasmInstr::I32Add,
                WasmInstr::LocalSet(8),
                WasmInstr::LocalGet(8),
                WasmInstr::I32Const(64),
                WasmInstr::I32GeU,
                WasmInstr::If {
                    result_ty: WasmBlockType::Empty,
                },
                WasmInstr::Then,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
                WasmInstr::Return,
                WasmInstr::End,
                WasmInstr::LocalGet(5),
                WasmInstr::LocalSet(4),
                WasmInstr::Br("$walk".to_owned()),
                WasmInstr::End,
                WasmInstr::End,
                WasmInstr::I32Const(ValueTag::UNDEFINED),
            ]);
            body
        })
}

/// Build the `$property_set` function.
