    let tracked_attr_count =
        (Layout::OBJECT_ACCESSOR_PROP_SHIFT - Layout::OBJECT_NON_CONFIGURABLE_SHIFT) as i32;
    let symbol_sentinel = Layout::SYMBOL_SENTINEL;

