fn tagged_number_sentinel(payload: i32) -> i32 {
    ValueTag::encode_reserved_number_payload(payload)
}

fn push_number_special_condition(body: &mut Vec<WasmInstr>) {
    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(tagged_number_sentinel(ValueTag::NAN_PAYLOAD)),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(tagged_number_sentinel(ValueTag::INFINITY_PAYLOAD)),
        WasmInstr::I32Eq,
        WasmInstr::I32Or,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(tagged_number_sentinel(ValueTag::NEG_INFINITY_PAYLOAD)),
        WasmInstr::I32Eq,
        WasmInstr::I32Or,
    ]);
}

