fn push_string_byte_load(
    body: &mut Vec<WasmInstr>,
    base_local: usize,
    index_local: usize,
    target_local: usize,
) {
    body.extend([
        WasmInstr::LocalGet(base_local),
        WasmInstr::I32Const(Layout::STRING_HEADER_SIZE as i32),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(index_local),
        WasmInstr::I32Add,
        WasmInstr::I32Load8U {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalSet(target_local),
    ]);
}

