/// Build the `$typeof` function.
///
/// Runtime string values are supplied by the native module assembly layer so
/// the function can return tagged string values without creating data segments
/// itself.
/// Remaining raw escape hatches: none.
pub fn build_typeof(strings: TypeOfStringValues) -> WasmFunction {
    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(1),
    ];

    push_return_if_tag(&mut body, 1, ValueTag::UNDEFINED, strings.undefined);
    push_return_if_tag(&mut body, 1, ValueTag::NULL, strings.object);
    push_return_if_tag(&mut body, 1, ValueTag::FALSE, strings.boolean);
    push_return_if_tag(&mut body, 1, ValueTag::TRUE, strings.boolean);

    body.extend([
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::NUMBER),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::BUILTIN_PARSE_INT_VALUE),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::BUILTIN_PARSE_FLOAT_VALUE),
        WasmInstr::I32Eq,
        WasmInstr::I32Or,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(strings.function),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::NUMBER),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32ShrU,
        WasmInstr::I32Const(ValueTag::DIRECT_LOCAL_TOKEN_PAYLOAD_BASE),
        WasmInstr::I32LtU,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32ShrU,
        WasmInstr::I32Const(ValueTag::NATIVE_ERROR_PAYLOAD_BASE),
        WasmInstr::I32GeU,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(strings.function),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::End,
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::NUMBER),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::NUMBER_SHIFT),
        WasmInstr::I32ShrU,
        WasmInstr::I32Const(ValueTag::DIRECT_LOCAL_TOKEN_PAYLOAD_BASE),
        WasmInstr::I32GeU,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(strings.function),
        WasmInstr::Return,
        WasmInstr::End,
    ]);

    push_return_if_tag(&mut body, 1, ValueTag::NUMBER, strings.number);
    push_return_if_tag(&mut body, 1, ValueTag::STRING, strings.string);

    body.extend([
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(ValueTag::OBJECT),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Const(Layout::GC_HEADER_SIZE as i32),
        WasmInstr::I32Sub,
        WasmInstr::I32Const(Layout::GC_FLAGS_AND_TYPE_OFFSET as i32),
        WasmInstr::I32Add,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::I32Const(Layout::GC_KIND_MASK as i32),
        WasmInstr::I32And,
        WasmInstr::I32Const(Layout::GC_KIND_BIGINT as i32),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(strings.bigint),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::I32Const(Layout::SYMBOL_SENTINEL),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(strings.symbol),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::I32Const(Layout::HEAP_NUMBER_SENTINEL),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(strings.number),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::I32Const(strings.object),
        WasmInstr::Return,
        WasmInstr::End,
    ]);

    push_return_if_tag(&mut body, 1, ValueTag::ARRAY, strings.object);
    body.push(WasmInstr::I32Const(strings.object));

    WasmFunction::new("$typeof")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

fn push_return_if_tag(body: &mut Vec<WasmInstr>, tag_local: usize, tag: i32, result_value: i32) {
    body.extend([
        WasmInstr::LocalGet(tag_local),
        WasmInstr::I32Const(tag),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(result_value),
        WasmInstr::Return,
        WasmInstr::End,
    ]);
}

/// Build the `$value_to_string_into` function.
///
/// Writes a JS value's string representation to `ptr` and returns the byte
/// length written. This covers primitive values, strings, heap-number and
/// bigint payloads, symbols, arrays, and ordinary object fallback.
/// Remaining raw escape hatches: none.
pub fn build_value_to_string_into(strings: ValueToStringRefs) -> WasmFunction {
    let mut body = Vec::new();

    push_copy_string_ref_if_value(&mut body, ValueTag::UNDEFINED, strings.undefined);
    push_copy_string_ref_if_value(&mut body, ValueTag::NULL, strings.null);
    push_copy_string_ref_if_value(&mut body, ValueTag::FALSE, strings.false_);
    push_copy_string_ref_if_value(&mut body, ValueTag::TRUE, strings.true_);
    push_store_literal_if_value(&mut body, ValueTag::encode_neg_zero(), "0");
    push_store_literal_if_value(&mut body, ValueTag::encode_infinity(), "Infinity");
    push_store_literal_if_value(&mut body, ValueTag::encode_neg_infinity(), "-Infinity");
    push_store_literal_if_value(&mut body, ValueTag::encode_nan(), "NaN");

    push_string_copy_branch(&mut body);
    push_object_to_string_branch(&mut body);
    push_array_to_string_branch(&mut body);
    push_number_to_string_tail(&mut body);

    WasmFunction::new("$value_to_string_into")
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 2: obj
        .local(WasmValType::I32) // local 3: len
        .local(WasmValType::I32) // local 4: n / total len
        .local(WasmValType::I32) // local 5: abs / start
        .local(WasmValType::I32) // local 6: i
        .local(WasmValType::I32) // local 7: j
        .local(WasmValType::I32) // local 8: tmp
        .local(WasmValType::I32) // local 9: desc
        .local(WasmValType::I32) // local 10: payload / digit
        .body(body)
}

fn push_copy_string_ref_if_value(
    body: &mut Vec<WasmInstr>,
    value: i32,
    string_ref: RuntimeStringRef,
) {
    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(value),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::I32Const(string_ref.ptr),
        WasmInstr::LocalGet(1),
        WasmInstr::I32Const(string_ref.len),
        WasmInstr::Call("$copy".to_owned()),
        WasmInstr::I32Const(string_ref.len),
        WasmInstr::Return,
        WasmInstr::End,
    ]);
}

fn push_store_literal_if_value(body: &mut Vec<WasmInstr>, value: i32, literal: &str) {
    body.extend([
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(value),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_store_literal_body(body, literal);
    body.extend([WasmInstr::Return, WasmInstr::End]);
}

fn push_store_literal_body(body: &mut Vec<WasmInstr>, literal: &str) {
    push_store_literal_prefix(body, literal);
    body.push(WasmInstr::I32Const(literal.len() as i32));
}

fn push_store_literal_prefix(body: &mut Vec<WasmInstr>, literal: &str) {
    for (index, byte) in literal.bytes().enumerate() {
        body.extend([
            WasmInstr::LocalGet(1),
            WasmInstr::I32Const(index as i32),
            WasmInstr::I32Add,
            WasmInstr::I32Const(byte as i32),
            WasmInstr::I32Store8 {
                align: 0,
                offset: 0,
            },
        ]);
    }
}

