/// Build the `$eval_indirect_host` function.
///
/// Non-string sources return unchanged. String sources delegate to the host
/// shim with a null environment and translate the host exception sentinel into
/// `$exception_pending`.
pub fn build_eval_indirect_host() -> WasmFunction {
    let result = 1;
    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Const(ValueTag::STRING),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(RuntimeConst::ZERO),
        WasmInstr::Call("$host_eval_indirect".to_owned()),
        WasmInstr::LocalSet(result),
    ];
    append_host_exception_bridge(&mut body, result);
    body.extend([
        WasmInstr::LocalGet(result),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
    ]);

    WasmFunction::new("$eval_indirect_host")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

fn append_host_exception_bridge(body: &mut Vec<WasmInstr>, result_local: usize) {
    body.extend([
        WasmInstr::LocalGet(result_local),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Const(ValueTag::ARRAY),
        WasmInstr::I32Eq,
        WasmInstr::LocalGet(result_local),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Const(Layout::ARRAY_CAPACITY_OFFSET as i32),
        WasmInstr::I32Add,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::I32Const(-2),
        WasmInstr::I32Eq,
        WasmInstr::I32And,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(result_local),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Const(Layout::ARRAY_HEADER_SIZE as i32),
        WasmInstr::I32Add,
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::GlobalSet("$exception_pending".to_owned()),
        WasmInstr::I32Const(ValueTag::UNDEFINED),
        WasmInstr::Return,
        WasmInstr::End,
    ]);
}

/// Build the `$eval_direct_host` function.
///
/// Non-string sources return unchanged. String sources delegate to the host
/// shim and translate the host exception sentinel into `$exception_pending`.
/// Remaining raw escape hatches: none.
pub fn build_eval_direct_host() -> WasmFunction {
    let result = 2;
    let mut body = vec![
        WasmInstr::LocalGet(0),
        WasmInstr::I32Const(ValueTag::TAG_MASK),
        WasmInstr::I32And,
        WasmInstr::I32Const(ValueTag::STRING),
        WasmInstr::I32Eq,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(0),
        WasmInstr::LocalGet(1),
        WasmInstr::Call("$host_eval_direct".to_owned()),
        WasmInstr::LocalSet(result),
    ];
    append_host_exception_bridge(&mut body, result);
    body.extend([
        WasmInstr::LocalGet(result),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(0),
    ]);

    WasmFunction::new("$eval_direct_host")
        .param(WasmValType::I32)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

fn build_host_call_bridge(symbol: &str, host_symbol: &str, params: usize) -> WasmFunction {
    let result = params;
    let mut body = Vec::new();
    for param in 0..params {
        body.push(WasmInstr::LocalGet(param));
    }
    body.push(WasmInstr::Call(host_symbol.to_owned()));
    body.push(WasmInstr::LocalSet(result));
    append_host_exception_bridge(&mut body, result);
    body.push(WasmInstr::LocalGet(result));

    let mut function = WasmFunction::new(symbol);
    for _ in 0..params {
        function = function.param(WasmValType::I32);
    }
    function
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

/// Build the `$function_compile_host` function.
///
/// Remaining raw escape hatches: none.
pub fn build_function_compile_host() -> WasmFunction {
    build_host_call_bridge("$function_compile_host", "$host_function_compile", 1)
}

