fn build_host_value_passthrough(symbol: &str, host_symbol: &str, params: usize) -> WasmFunction {
    let mut body = Vec::new();
    for param in 0..params {
        body.push(WasmInstr::LocalGet(param));
    }
    body.push(WasmInstr::Call(host_symbol.to_owned()));

    let mut function = WasmFunction::new(symbol);
    for _ in 0..params {
        function = function.param(WasmValType::I32);
    }
    function.result(WasmValType::I32).body(body)
}

