fn push_ascii_range_predicate(body: &mut Vec<WasmInstr>, value_local: usize, start: i32, end: i32) {
    body.extend([
        WasmInstr::LocalGet(value_local),
        WasmInstr::I32Const(start),
        WasmInstr::I32GeU,
        WasmInstr::LocalGet(value_local),
        WasmInstr::I32Const(end),
        WasmInstr::I32LeU,
        WasmInstr::I32And,
    ]);
}

fn push_ascii_eq_predicate(body: &mut Vec<WasmInstr>, value_local: usize, value: u8) {
    body.extend([
        WasmInstr::LocalGet(value_local),
        WasmInstr::I32Const(value as i32),
        WasmInstr::I32Eq,
    ]);
}

fn push_uri_encode_safe_predicate(
    body: &mut Vec<WasmInstr>,
    value_local: usize,
    keep_reserved: bool,
) {
    push_ascii_range_predicate(body, value_local, RuntimeConst::ASCII_ZERO, 57);
    push_ascii_range_predicate(body, value_local, 65, 90);
    body.push(WasmInstr::I32Or);
    push_ascii_range_predicate(body, value_local, 97, 122);
    body.push(WasmInstr::I32Or);

    for ch in b"-_.!~*'()" {
        push_ascii_eq_predicate(body, value_local, *ch);
        body.push(WasmInstr::I32Or);
    }

    if keep_reserved {
        for ch in b";,/?:@&=+$#" {
            push_ascii_eq_predicate(body, value_local, *ch);
            body.push(WasmInstr::I32Or);
        }
    }
}

fn push_uri_output_addr(
    body: &mut Vec<WasmInstr>,
    out_local: usize,
    out_pos_local: usize,
    offset: i32,
) {
    body.extend([
        WasmInstr::LocalGet(out_local),
        WasmInstr::I32Const(Layout::STRING_HEADER_SIZE as i32),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(out_pos_local),
    ]);
    if offset != 0 {
        body.extend([WasmInstr::I32Const(offset), WasmInstr::I32Add]);
    }
    body.push(WasmInstr::I32Add);
}

fn push_hex_nibble_value(body: &mut Vec<WasmInstr>, nibble_local: usize) {
    body.extend([
        WasmInstr::LocalGet(nibble_local),
        WasmInstr::I32Const(10),
        WasmInstr::I32LtU,
        WasmInstr::If {
            result_ty: WasmBlockType::Result(WasmValType::I32),
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(nibble_local),
        WasmInstr::I32Const(48),
        WasmInstr::I32Add,
        WasmInstr::Else,
        WasmInstr::LocalGet(nibble_local),
        WasmInstr::I32Const(55),
        WasmInstr::I32Add,
        WasmInstr::End,
    ]);
}

