fn build_uri_percent_encoder(symbol: &str, keep_reserved: bool) -> WasmFunction {
    let str_local = 0;
    let obj_local = 1;
    let len_local = 2;
    let index_local = 3;
    let out_local = 4;
    let out_pos_local = 5;
    let byte_local = 6;
    let nibble_local = 7;

    let mut body = vec![
        WasmInstr::LocalGet(str_local),
        WasmInstr::Call("$is_string".to_owned()),
        WasmInstr::I32Eqz,
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
        WasmInstr::LocalGet(str_local),
        WasmInstr::Return,
        WasmInstr::End,
        WasmInstr::LocalGet(str_local),
        WasmInstr::I32Const(ValueTag::HEAP_MASK),
        WasmInstr::I32And,
        WasmInstr::LocalSet(obj_local),
        WasmInstr::LocalGet(obj_local),
        WasmInstr::I32Load {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalSet(len_local),
        WasmInstr::I32Const(Layout::STRING_HEADER_SIZE as i32),
        WasmInstr::LocalGet(len_local),
        WasmInstr::I32Const(3),
        WasmInstr::I32Mul,
        WasmInstr::I32Add,
        WasmInstr::Call("$alloc_heap".to_owned()),
        WasmInstr::LocalSet(out_local),
        WasmInstr::I32Const(0),
        WasmInstr::LocalSet(index_local),
        WasmInstr::I32Const(0),
        WasmInstr::LocalSet(out_pos_local),
        WasmInstr::Block("$done".to_owned()),
        WasmInstr::Loop("$scan".to_owned()),
        WasmInstr::LocalGet(index_local),
        WasmInstr::LocalGet(len_local),
        WasmInstr::I32GeU,
        WasmInstr::BrIf("$done".to_owned()),
        WasmInstr::LocalGet(obj_local),
        WasmInstr::I32Const(Layout::STRING_HEADER_SIZE as i32),
        WasmInstr::I32Add,
        WasmInstr::LocalGet(index_local),
        WasmInstr::I32Add,
        WasmInstr::I32Load8U {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalSet(byte_local),
    ];

    push_uri_encode_safe_predicate(&mut body, byte_local, keep_reserved);
    body.extend([
        WasmInstr::If {
            result_ty: WasmBlockType::Empty,
        },
        WasmInstr::Then,
    ]);
    push_uri_output_addr(&mut body, out_local, out_pos_local, 0);
    body.extend([
        WasmInstr::LocalGet(byte_local),
        WasmInstr::I32Store8 {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalGet(out_pos_local),
        WasmInstr::I32Const(1),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(out_pos_local),
        WasmInstr::Else,
    ]);
    push_uri_output_addr(&mut body, out_local, out_pos_local, 0);
    body.extend([
        WasmInstr::I32Const(37),
        WasmInstr::I32Store8 {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalGet(byte_local),
        WasmInstr::I32Const(4),
        WasmInstr::I32ShrU,
        WasmInstr::LocalSet(nibble_local),
    ]);
    push_uri_output_addr(&mut body, out_local, out_pos_local, 1);
    push_hex_nibble_value(&mut body, nibble_local);
    body.extend([
        WasmInstr::I32Store8 {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalGet(byte_local),
        WasmInstr::I32Const(15),
        WasmInstr::I32And,
        WasmInstr::LocalSet(nibble_local),
    ]);
    push_uri_output_addr(&mut body, out_local, out_pos_local, 2);
    push_hex_nibble_value(&mut body, nibble_local);
    body.extend([
        WasmInstr::I32Store8 {
            align: 0,
            offset: 0,
        },
        WasmInstr::LocalGet(out_pos_local),
        WasmInstr::I32Const(3),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(out_pos_local),
        WasmInstr::End,
        WasmInstr::LocalGet(index_local),
        WasmInstr::I32Const(1),
        WasmInstr::I32Add,
        WasmInstr::LocalSet(index_local),
        WasmInstr::Br("$scan".to_owned()),
        WasmInstr::End,
        WasmInstr::End,
        WasmInstr::LocalGet(out_local),
        WasmInstr::LocalGet(out_pos_local),
        WasmInstr::I32Store {
            align: 2,
            offset: 0,
        },
        WasmInstr::LocalGet(out_local),
        WasmInstr::I32Const(ValueTag::STRING),
        WasmInstr::I32Or,
    ]);

    WasmFunction::new(symbol)
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

