///
/// Materializes the value's runtime string representation as a tagged heap
/// string. For symbols, `$value_to_string_into` follows the native heap symbol
/// layout and writes `Symbol(description)` into the scratch buffer.
///
/// Remaining raw escape hatches: none.
pub fn build_symbol_to_string() -> WasmFunction {
    let string_header = Layout::STRING_HEADER_SIZE as i32;
    let scratch = Layout::SCRATCH_OFFSET as i32;
    let string_tag = ValueTag::STRING;

    WasmFunction::new("$symbol_to_string")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 1: $len
        .local(WasmValType::I32) // local 2: $ptr
        .body(vec![
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(scratch),
            WasmInstr::Call("$value_to_string_into".to_owned()),
            WasmInstr::LocalSet(1),
            WasmInstr::I32Const(string_header),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Add,
            WasmInstr::Call("$alloc_heap".to_owned()),
            WasmInstr::LocalSet(2),
            WasmInstr::LocalGet(2),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::I32Const(scratch),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(string_header),
            WasmInstr::I32Add,
            WasmInstr::LocalGet(1),
            WasmInstr::Call("$copy".to_owned()),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(string_tag),
            WasmInstr::I32Or,
        ])
}

/// Build the `$error_message` function.
///
/// Converts a value to a string error message.  If the value is `undefined`,
/// returns an empty string.
///
/// Locals: `$len` (index 1), `$ptr` (index 2).
///
/// Remaining raw escape hatches: none.
pub fn build_error_message() -> WasmFunction {
    let string_header = Layout::STRING_HEADER_SIZE as i32;
    let scratch = Layout::SCRATCH_OFFSET as i32;
    let undefined_tag = ValueTag::UNDEFINED;
    let string_tag = ValueTag::STRING;
    let zero = RuntimeConst::ZERO;

    WasmFunction::new("$error_message")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32) // local 1: $len
        .local(WasmValType::I32) // local 2: $ptr
        .body(vec![
            // if (v == undefined) { alloc empty string, return it }
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(undefined_tag),
            WasmInstr::I32Eq,
            WasmInstr::If {
                result_ty: WasmBlockType::Empty,
            },
            WasmInstr::Then,
            WasmInstr::I32Const(string_header),
            WasmInstr::Call("$alloc_heap".to_owned()),
            WasmInstr::LocalSet(2),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(zero),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(string_tag),
            WasmInstr::I32Or,
            WasmInstr::Return,
            WasmInstr::End,
            // $len = value_to_string_into(v, SCRATCH)
            WasmInstr::LocalGet(0),
            WasmInstr::I32Const(scratch),
            WasmInstr::Call("$value_to_string_into".to_owned()),
            WasmInstr::LocalSet(1),
            // $ptr = alloc_heap(STRING_HEADER_SIZE + $len)
            WasmInstr::I32Const(string_header),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Add,
            WasmInstr::Call("$alloc_heap".to_owned()),
            WasmInstr::LocalSet(2),
            // store length at $ptr
            WasmInstr::LocalGet(2),
            WasmInstr::LocalGet(1),
            WasmInstr::I32Store {
                align: 2,
                offset: 0,
            },
            // copy(SCRATCH, $ptr + STRING_HEADER_SIZE, $len)
            WasmInstr::I32Const(scratch),
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(string_header),
            WasmInstr::I32Add,
            WasmInstr::LocalGet(1),
            WasmInstr::Call("$copy".to_owned()),
            // return $ptr | STRING_TAG
            WasmInstr::LocalGet(2),
            WasmInstr::I32Const(string_tag),
            WasmInstr::I32Or,
        ])
}

/// Build the `$log` function.
///
/// Writes a value's string representation to stdout with a newline.
/// Remaining raw escape hatches: none.
pub fn build_log(newline_offset: i32) -> WasmFunction {
    build_log_function("$log", newline_offset, LogSink::RuntimeWrite)
}

/// Build the `$log_warn` function.
///
/// Remaining raw escape hatches: none.
pub fn build_log_warn(newline_offset: i32) -> WasmFunction {
    build_log_function("$log_warn", newline_offset, LogSink::FdWriteStderr)
}

/// Build the `$log_error` function.
///
/// Remaining raw escape hatches: none.
pub fn build_log_error(newline_offset: i32) -> WasmFunction {
    build_log_function("$log_error", newline_offset, LogSink::FdWriteStderr)
}

/// Build the `$console_group_start` function.
///
/// Remaining raw escape hatches: none.
pub fn build_console_group_start(newline_offset: i32) -> WasmFunction {
    let mut body = console_write_line_body(newline_offset);
    body.extend([
        WasmInstr::GlobalGet("$console_indent_level".to_owned()),
        WasmInstr::I32Const(RuntimeConst::ONE),
        WasmInstr::I32Add,
        WasmInstr::GlobalSet("$console_indent_level".to_owned()),
        WasmInstr::I32Const(ValueTag::UNDEFINED),
    ]);

    WasmFunction::new("$console_group_start")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

/// Build the `$console_group_end` function.
///
/// Remaining raw escape hatches: none.
pub fn build_console_group_end() -> WasmFunction {
    WasmFunction::new("$console_group_end")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .body(vec![
            WasmInstr::GlobalGet("$console_indent_level".to_owned()),
            WasmInstr::I32Const(RuntimeConst::ONE),
            WasmInstr::I32Sub,
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::GlobalGet("$console_indent_level".to_owned()),
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I32GtU,
            WasmInstr::Select,
            WasmInstr::GlobalSet("$console_indent_level".to_owned()),
            WasmInstr::I32Const(ValueTag::UNDEFINED),
        ])
}

/// Build the `$console_time_start` function.
///
/// Remaining raw escape hatches: none.
pub fn build_console_time_start() -> WasmFunction {
    WasmFunction::new("$console_time_start")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .body(vec![
            WasmInstr::I32Const(RuntimeConst::ZERO),
            WasmInstr::I64Const(0),
            WasmInstr::I32Const(Layout::SCRATCH_OFFSET as i32 + 1024),
            WasmInstr::Call("$clock_time_get".to_owned()),
            WasmInstr::Drop,
            WasmInstr::I32Const(ValueTag::UNDEFINED),
        ])
}

/// Build the `$console_time_end` function.
///
/// Remaining raw escape hatches: none.
pub fn build_console_time_end(newline_offset: i32) -> WasmFunction {
    let mut body = console_write_line_body(newline_offset);
    body.push(WasmInstr::I32Const(ValueTag::UNDEFINED));

    WasmFunction::new("$console_time_end")
        .param(WasmValType::I32)
        .result(WasmValType::I32)
        .local(WasmValType::I32)
        .body(body)
}

