    #[test]
    fn typed_bigint_mixed_arithmetic_type_error_emits_valid_wasm() {
        let f = build_bigint_mixed_arithmetic_type_error(BigIntMixedArithmeticErrorData {
            diagnostic: RuntimeStringRef { ptr: 128, len: 64 },
            message_key: ValueTag::STRING | 256,
            message_value: ValueTag::STRING | 320,
        });
        let module = WasmModule::new()
            .memory(WasmMemory::new(1, 1))
            .global(WasmGlobal::i32_mut("$exception_handler_depth", 0))
            .global(WasmGlobal::i32_mut("$exception_pending", 0))
            .function(f.clone())
            .function(stub_function(
                "$write",
                &[WasmValType::I32, WasmValType::I32],
                &[],
            ))
            .function(stub_function(
                "$alloc_heap",
                &[WasmValType::I32],
                &[WasmValType::I32],
            ));
        let wasm = emit_wasm_module_binary(&module).expect("typed runtime module should encode");
        wasmparser::Validator::new()
            .validate_all(&wasm)
            .expect("typed BigInt mixed arithmetic TypeError helper should validate");

        assert!(wasm.starts_with(b"\0asm"));
        assert!(f.body.iter().any(
            |instr| matches!(instr, WasmInstr::GlobalSet(symbol) if symbol == "$exception_pending")
        ));
        assert!(
            f.body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );
    }

