    #[test]
    fn typed_object_global_helpers_emit_valid_wasm() {
        let object_proto = build_object_prototype();
        let proto_module = WasmModule::new()
            .memory(WasmMemory::new(1, 1))
            .global(WasmGlobal::i32_mut("$object_prototype_object", 0))
            .function(object_proto.clone())
            .function(stub_function(
                "$alloc_heap",
                &[WasmValType::I32],
                &[WasmValType::I32],
            ));
        let proto_wasm =
            emit_wasm_module_binary(&proto_module).expect("object prototype module should encode");
        wasmparser::Validator::new()
            .validate_all(&proto_wasm)
            .expect("object prototype module should validate");
        assert!(proto_wasm.starts_with(b"\0asm"));
        assert!(object_proto.body.iter().any(
            |instr| matches!(instr, WasmInstr::GlobalSet(symbol) if symbol == "$object_prototype_object")
        ));

        let global_this = build_global_this();
        let global_module = WasmModule::new()
            .memory(WasmMemory::new(1, 1))
            .global(WasmGlobal::i32_mut("$global_this_object", 0))
            .function(global_this.clone())
            .function(stub_function(
                "$object_create",
                &[WasmValType::I32],
                &[WasmValType::I32],
            ));
        let global_wasm =
            emit_wasm_module_binary(&global_module).expect("global this module should encode");
        wasmparser::Validator::new()
            .validate_all(&global_wasm)
            .expect("global this module should validate");
        assert!(global_wasm.starts_with(b"\0asm"));
        assert!(global_this.body.iter().any(
            |instr| matches!(instr, WasmInstr::GlobalSet(symbol) if symbol == "$global_this_object")
        ));

        for f in [object_proto, global_this] {
            assert!(
                f.body
                    .iter()
                    .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
            );
        }
    }

