    #[test]
    fn typed_object_string_helpers_emit_valid_wasm() {
        let strings = ObjectToStringValues {
            undefined: 1000,
            null: 1004,
            boolean: 1008,
            number: 1012,
            string: 1016,
            function: 1020,
            array: 1024,
            bigint: 1028,
            symbol: 1032,
            object: 1036,
        };
        let object_to_string = build_object_to_string(strings);
        let wasm = encode_and_validate_with_stubs(object_to_string.clone(), vec![]);

        assert!(wasm.starts_with(b"\0asm"));
        assert!(object_to_string.body.iter().any(
            |instr| matches!(instr, WasmInstr::I32Const(value) if *value == strings.function)
        ));
        assert!(object_to_string.body.iter().any(
            |instr| matches!(instr, WasmInstr::I32Const(value) if *value == Layout::SYMBOL_SENTINEL)
        ));
        assert!(
            object_to_string
                .body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );

        let locale = build_object_to_locale_string();
        let locale_wasm = encode_and_validate_with_stubs(
            locale.clone(),
            vec![stub_function(
                "$object_to_string",
                &[WasmValType::I32],
                &[WasmValType::I32],
            )],
        );
        assert!(locale_wasm.starts_with(b"\0asm"));
        assert!(locale.body.iter().any(
            |instr| matches!(instr, WasmInstr::Call(symbol) if symbol == "$object_to_string")
        ));

        let error = build_error_to_string(ErrorToStringData {
            name_key: RuntimeStringRef { ptr: 2000, len: 4 },
            message_key: RuntimeStringRef { ptr: 2010, len: 7 },
            empty_string: 2020,
            error_string: 2030,
            colon_space: 2040,
        });
        let error_wasm = encode_and_validate_with_stubs(
            error.clone(),
            vec![
                stub_function(
                    "$property_get",
                    &[WasmValType::I32, WasmValType::I32, WasmValType::I32],
                    &[WasmValType::I32],
                ),
                stub_function(
                    "$concat",
                    &[WasmValType::I32, WasmValType::I32],
                    &[WasmValType::I32],
                ),
            ],
        );
        assert!(error_wasm.starts_with(b"\0asm"));
        assert!(
            error
                .body
                .iter()
                .any(|instr| matches!(instr, WasmInstr::Call(symbol) if symbol == "$property_get"))
        );
        assert!(
            error
                .body
                .iter()
                .filter(|instr| matches!(instr, WasmInstr::Call(symbol) if symbol == "$concat"))
                .count()
                == 2
        );
        assert!(
            error
                .body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );
    }

