    #[test]
    fn typed_dynamic_host_wrappers_emit_valid_wasm() {
        let cases = [
            (
                build_eval_direct_host(),
                "$host_eval_direct",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_eval_indirect_host(),
                "$host_eval_indirect",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_function_compile_host(),
                "$host_function_compile",
                vec![WasmValType::I32],
            ),
            (
                build_function_call_host(),
                "$host_function_call",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_function_call_method_host(),
                "$host_function_call_method",
                vec![WasmValType::I32, WasmValType::I32, WasmValType::I32],
            ),
            (
                build_function_construct_host(),
                "$host_function_construct",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_json_stringify(),
                "$host_json_stringify",
                vec![WasmValType::I32, WasmValType::I32, WasmValType::I32],
            ),
            (
                build_json_parse(),
                "$host_json_parse",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_map(),
                "$host_iterator_map",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_filter(),
                "$host_iterator_filter",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_take(),
                "$host_iterator_take",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_drop(),
                "$host_iterator_drop",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_to_array(),
                "$host_iterator_to_array",
                vec![WasmValType::I32],
            ),
            (
                build_iterator_reduce(),
                "$host_iterator_reduce",
                vec![
                    WasmValType::I32,
                    WasmValType::I32,
                    WasmValType::I32,
                    WasmValType::I32,
                ],
            ),
            (
                build_iterator_for_each(),
                "$host_iterator_for_each",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_some(),
                "$host_iterator_some",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_every(),
                "$host_iterator_every",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_iterator_find(),
                "$host_iterator_find",
                vec![WasmValType::I32, WasmValType::I32],
            ),
        ];

        for (f, host_symbol, params) in cases {
            let module = WasmModule::new()
                .memory(WasmMemory::new(1, 1))
                .global(WasmGlobal::i32_mut("$exception_pending", 0))
                .function(f.clone())
                .function(stub_function(host_symbol, &params, &[WasmValType::I32]));
            let wasm =
                emit_wasm_module_binary(&module).expect("typed dynamic host helper should encode");
            wasmparser::Validator::new()
                .validate_all(&wasm)
                .expect("typed dynamic host helper should validate");
            assert!(wasm.starts_with(b"\0asm"));
            assert!(
                f.body
                    .iter()
                    .any(|instr| matches!(instr, WasmInstr::Call(symbol) if symbol == host_symbol))
            );
            assert!(f.body.iter().any(
                |instr| matches!(instr, WasmInstr::GlobalSet(symbol) if symbol == "$exception_pending")
            ));
            assert!(
                f.body
                    .iter()
                    .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
            );
        }

        let dollar_eval = build_dollar_262_eval();
        let dollar_eval_wasm = encode_and_validate_with_stubs(
            dollar_eval.clone(),
            vec![stub_function(
                "$eval_indirect_host",
                &[WasmValType::I32],
                &[WasmValType::I32],
            )],
        );
        assert!(dollar_eval_wasm.starts_with(b"\0asm"));
        assert!(dollar_eval.body.iter().any(
            |instr| matches!(instr, WasmInstr::Call(symbol) if symbol == "$eval_indirect_host")
        ));
        assert!(
            dollar_eval
                .body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );
    }

    #[test]
    fn typed_node_host_file_path_process_wrappers_emit_valid_wasm() {
        let value_cases = [
            (
                build_path_join(),
                "$host_path_join",
                vec![WasmValType::I32, WasmValType::I32],
            ),
            (
                build_path_resolve(),
                "$host_path_resolve",
                vec![WasmValType::I32],
            ),
            (
                build_path_basename(),
                "$host_path_basename",
                vec![WasmValType::I32],
            ),
            (
                build_path_dirname(),
                "$host_path_dirname",
                vec![WasmValType::I32],
            ),
            (
                build_crypto_random_bytes(),
                "$host_crypto_random_bytes",
                vec![WasmValType::I32],
            ),
        ];

        for (f, host_symbol, params) in value_cases {
            let wasm = encode_and_validate_with_stubs(
                f.clone(),
                vec![stub_function(host_symbol, &params, &[WasmValType::I32])],
            );
            assert!(wasm.starts_with(b"\0asm"));
            assert_eq!(f.params, params);
            assert_eq!(f.results, vec![WasmValType::I32]);
            assert!(
                f.body
                    .iter()
                    .any(|instr| matches!(instr, WasmInstr::Call(symbol) if symbol == host_symbol))
            );
            assert!(
                f.body
                    .iter()
                    .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
            );
        }

        let process_exit = build_process_exit();
        let process_exit_wasm = encode_and_validate_with_stubs(
            process_exit.clone(),
            vec![stub_function(
                "$host_process_exit",
                &[WasmValType::I32],
                &[],
            )],
        );
        assert!(process_exit_wasm.starts_with(b"\0asm"));
        assert_eq!(process_exit.params, vec![WasmValType::I32]);
        assert!(process_exit.results.is_empty());
        assert!(process_exit.body.iter().any(
            |instr| matches!(instr, WasmInstr::Call(symbol) if symbol == "$host_process_exit")
        ));
        assert!(
            process_exit
                .body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );

        let wasi_fs_stubs = || {
            vec![
                stub_function(
                    "$path_open",
                    &[
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I64,
                        WasmValType::I64,
                        WasmValType::I32,
                        WasmValType::I32,
                    ],
                    &[WasmValType::I32],
                ),
                stub_function(
                    "$fd_read",
                    &[
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I32,
                    ],
                    &[WasmValType::I32],
                ),
                stub_function(
                    "$fd_write",
                    &[
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I32,
                        WasmValType::I32,
                    ],
                    &[WasmValType::I32],
                ),
                stub_function("$fd_close", &[WasmValType::I32], &[WasmValType::I32]),
                stub_function("$alloc_heap", &[WasmValType::I32], &[WasmValType::I32]),
                stub_function(
                    "$copy",
                    &[WasmValType::I32, WasmValType::I32, WasmValType::I32],
                    &[],
                ),
            ]
        };

        let fs_read = build_fs_read_file_sync();
        let fs_read_wasm = encode_and_validate_with_stubs(fs_read.clone(), wasi_fs_stubs());
        assert!(fs_read_wasm.starts_with(b"\0asm"));
        assert_eq!(fs_read.params, vec![WasmValType::I32, WasmValType::I32]);
        assert_eq!(fs_read.results, vec![WasmValType::I32]);
        for symbol in [
            "$path_open",
            "$fd_read",
            "$fd_close",
            "$alloc_heap",
            "$copy",
        ] {
            assert!(
                fs_read
                    .body
                    .iter()
                    .any(|instr| matches!(instr, WasmInstr::Call(call) if call == symbol)),
                "expected {symbol} call"
            );
        }
        assert!(
            fs_read
                .body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );

        let fs_write = build_fs_write_file_sync();
        let fs_write_wasm = encode_and_validate_with_stubs(fs_write.clone(), wasi_fs_stubs());
        assert!(fs_write_wasm.starts_with(b"\0asm"));
        assert_eq!(fs_write.params, vec![WasmValType::I32, WasmValType::I32]);
        assert_eq!(fs_write.results, vec![WasmValType::I32]);
        for symbol in ["$path_open", "$fd_write", "$fd_close"] {
            assert!(
                fs_write
                    .body
                    .iter()
                    .any(|instr| matches!(instr, WasmInstr::Call(call) if call == symbol)),
                "expected {symbol} call"
            );
        }
        assert!(
            fs_write
                .body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );

        let fs_append = build_fs_append_file_sync();
        let fs_append_wasm = encode_and_validate_with_stubs(
            fs_append.clone(),
            vec![stub_function(
                "$host_fs_append_file_sync",
                &[WasmValType::I32, WasmValType::I32],
                &[],
            )],
        );
        assert!(fs_append_wasm.starts_with(b"\0asm"));
        assert_eq!(fs_append.params, vec![WasmValType::I32, WasmValType::I32]);
        assert_eq!(fs_append.results, vec![WasmValType::I32]);
        assert!(fs_append.body.iter().any(
            |instr| matches!(instr, WasmInstr::Call(symbol) if symbol == "$host_fs_append_file_sync")
        ));
        assert!(
            fs_append
                .body
                .iter()
                .all(|instr| !matches!(instr, WasmInstr::Raw(_)))
        );
    }

